import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { ReactQueryDevtools } from '@tanstack/react-query-devtools';
import { ThemeProvider } from '@/contexts/ThemeContext';
import { ConditionalAuthProvider } from '@/components/auth/ConditionalAuthProvider';
import { ProtectedRoute } from '@/components/auth/AuthGuards';
import { RoleBasedRedirect } from '@/components/auth/RoleBasedRedirect';
import { ApiAuthInitializer } from '@/components/auth/ApiAuthInitializer';
import { Layout } from '@/components/layout/Layout';
import { APP_ROLES } from '@/config/authConfig';

// Page components
import { Dashboard } from '@/pages/Dashboard';
import { UploadAnalyze, Sessions, SessionDetail, Predictions, ControlPanel, SystemHealth, NotFound } from '@/pages';
import GroupSessionsDetail from '@/pages/GroupSessionsDetail';
import DamTestBench from '@/pages/DamTestBench';

// Create React Query client
const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      retry: (failureCount, error) => {
        // Don't retry on 4xx errors except 408 (timeout)
        if (error && typeof error === 'object' && 'code' in error) {
          const errorCode = (error as any).code;
          if (errorCode?.startsWith('HTTP_4') && errorCode !== 'HTTP_408') {
            return false;
          }
        }
        return failureCount < 3;
      },
      staleTime: 5 * 60 * 1000, // 5 minutes
      refetchOnWindowFocus: false,
    },
    mutations: {
      retry: 1,
    },
  },
});

function App() {
  return (
    <QueryClientProvider client={queryClient}>
      <ThemeProvider>
        <ConditionalAuthProvider>
          <ApiAuthInitializer>
            <Router>
              <Layout>
                <Routes>
                    {/* Control Panel route - accessible to both Admin and Control Panel roles */}
                    <Route
                      path="/"
                      element={
                        <ProtectedRoute requireRoles={[APP_ROLES.ADMIN, APP_ROLES.CONTROL_PANEL]}>
                          <RoleBasedRedirect />
                          <Dashboard />
                        </ProtectedRoute>
                      }
                    />

                    {/* Admin-only routes */}
                    <Route
                      path="/upload"
                      element={
                        <ProtectedRoute requireRoles={[APP_ROLES.ADMIN]}>
                          <UploadAnalyze />
                        </ProtectedRoute>
                      }
                    />
                    <Route
                      path="/sessions"
                      element={
                        <ProtectedRoute requireRoles={[APP_ROLES.ADMIN]}>
                          <Sessions />
                        </ProtectedRoute>
                      }
                    />
                    <Route
                      path="/sessions/:sessionId"
                      element={
                        <ProtectedRoute requireRoles={[APP_ROLES.ADMIN]}>
                          <SessionDetail />
                        </ProtectedRoute>
                      }
                    />
                    <Route
                      path="/groups/:groupId/sessions"
                      element={
                        <ProtectedRoute requireRoles={[APP_ROLES.ADMIN]}>
                          <GroupSessionsDetail />
                        </ProtectedRoute>
                      }
                    />
                    <Route
                      path="/predictions"
                      element={
                        <ProtectedRoute requireRoles={[APP_ROLES.ADMIN]}>
                          <Predictions />
                        </ProtectedRoute>
                      }
                    />
                    <Route
                      path="/summary"
                      element={
                        <ProtectedRoute requireRoles={[APP_ROLES.ADMIN, APP_ROLES.CONTROL_PANEL]}>
                          <ControlPanel />
                        </ProtectedRoute>
                      }
                    />

                    <Route
                      path="/health"
                      element={
                        <ProtectedRoute requireRoles={[APP_ROLES.ADMIN]}>
                          <SystemHealth />
                        </ProtectedRoute>
                      }
                    />

                    {/* DAM test bench — URL-only, not in nav */}
                    <Route path="/dam-test" element={<DamTestBench />} />

                    {/* 404 page */}
                    <Route path="*" element={<NotFound />} />
                  </Routes>
                </Layout>
              </Router>
            </ApiAuthInitializer>
          </ConditionalAuthProvider>
        </ThemeProvider>

        {/* React Query DevTools (only in development) */}
        {import.meta.env.DEV && <ReactQueryDevtools initialIsOpen={false} />}
      </QueryClientProvider>
  );
}

export default App;

import React, { useState, useEffect } from 'react';
import { DSM5ConditionData } from '../types/dsm5Types';
import { dsm5Service } from '../services/dsm5Service';
import { createAppError } from '../utils';
import { Logger } from '@/utils/logger';

const log = Logger.create('DSM5ConditionSelector');

interface DSM5ConditionSelectorProps {
  selectedConditions: string[];
  onSelectionChange: (selectedConditionIds: string[]) => void;
  maxSelections?: number;
  disabled?: boolean;
  className?: string;
}

interface DSM5ConditionCategory {
  category: string;
  conditions: DSM5ConditionData[];
}

export const DSM5ConditionSelector: React.FC<DSM5ConditionSelectorProps> = ({
  selectedConditions,
  onSelectionChange,
  maxSelections = 5,
  disabled = false,
  className = ''
}) => {
  const [availableConditions, setAvailableConditions] = useState<DSM5ConditionData[]>([]);
  const [categorizedConditions, setCategorizedConditions] = useState<DSM5ConditionCategory[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedCategory, setSelectedCategory] = useState<string>('all');
  const [expandedCategories, setExpandedCategories] = useState<Set<string>>(new Set());

  useEffect(() => {
    loadAvailableConditions();
  }, []);

  useEffect(() => {
    categorizeConditions();
  }, [availableConditions, searchTerm, selectedCategory]);

  const loadAvailableConditions = async () => {
    try {
      setLoading(true);
      setError(null);

      const conditions = await dsm5Service.getAvailableConditions({
        includeDetails: false
      });

      setAvailableConditions(conditions);
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Failed to load DSM-5 conditions';
      const error = createAppError('DSM5_LOAD_ERROR', errorMessage);
      setError(error.message);
      log.error('Error loading DSM-5 conditions', error);
    } finally {
      setLoading(false);
    }
  };

  const categorizeConditions = () => {
    let filteredConditions = availableConditions;

    // Apply search filter
    if (searchTerm.trim()) {
      const searchLower = searchTerm.toLowerCase();
      filteredConditions = filteredConditions.filter(condition =>
        condition.name.toLowerCase().includes(searchLower) ||
        condition.description.toLowerCase().includes(searchLower) ||
        condition.code.toLowerCase().includes(searchLower)
      );
    }

    // Apply category filter
    if (selectedCategory !== 'all') {
      filteredConditions = filteredConditions.filter(condition =>
        condition.category === selectedCategory
      );
    }

    // Group by category
    const categoryMap = new Map<string, DSM5ConditionData[]>();

    filteredConditions.forEach(condition => {
      const category = condition.category || 'Other';
      if (!categoryMap.has(category)) {
        categoryMap.set(category, []);
      }
      categoryMap.get(category)!.push(condition);
    });

    // Convert to array and sort
    const categorized = Array.from(categoryMap.entries())
      .map(([category, conditions]) => ({
        category,
        conditions: conditions.sort((a, b) => a.name.localeCompare(b.name))
      }))
      .sort((a, b) => a.category.localeCompare(b.category));

    setCategorizedConditions(categorized);

    // Auto-expand categories with few items or if searching
    if (searchTerm.trim() || categorized.length <= 3) {
      setExpandedCategories(new Set(categorized.map(c => c.category)));
    }
  };

  const handleConditionToggle = (conditionId: string) => {
    if (disabled) return;

    const newSelection = selectedConditions.includes(conditionId)
      ? selectedConditions.filter(id => id !== conditionId)
      : [...selectedConditions, conditionId];

    // Enforce max selections limit
    if (newSelection.length <= maxSelections) {
      onSelectionChange(newSelection);
    }
  };

  const handleCategoryToggle = (category: string) => {
    const newExpanded = new Set(expandedCategories);
    if (newExpanded.has(category)) {
      newExpanded.delete(category);
    } else {
      newExpanded.add(category);
    }
    setExpandedCategories(newExpanded);
  };

  const handleSelectAll = () => {
    if (disabled) return;

    const visibleConditions = categorizedConditions.flatMap(cat => cat.conditions);
    const allIds = visibleConditions.map(c => c.id);
    const limitedSelection = allIds.slice(0, maxSelections);
    onSelectionChange(limitedSelection);
  };

  const handleClearAll = () => {
    if (!disabled) {
      onSelectionChange([]);
    }
  };

  const getAvailableCategories = () => {
    const categories = [...new Set(availableConditions.map(c => c.category))].sort();
    return ['all', ...categories];
  };

  if (loading) {
    return (
      <div className={`space-y-4 ${className}`}>
        <div className="flex items-center justify-center p-8 bg-gray-50 dark:bg-gray-700 rounded-lg border border-gray-200 dark:border-gray-600">
          <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600"></div>
          <span className="ml-3 text-gray-600 dark:text-gray-400">Loading DSM-5 conditions...</span>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className={`space-y-4 ${className}`}>
        <div className="p-4 bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-lg">
          <div className="flex">
            <div className="flex-shrink-0">
              <svg className="h-5 w-5 text-red-400" viewBox="0 0 20 20" fill="currentColor" aria-hidden="true">
                <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zM8.707 7.293a1 1 0 00-1.414 1.414L8.586 10l-1.293 1.293a1 1 0 101.414 1.414L10 11.414l1.293 1.293a1 1 0 001.414-1.414L11.414 10l1.293-1.293a1 1 0 00-1.414-1.414L10 8.586 8.707 7.293z" clipRule="evenodd" />
              </svg>
            </div>
            <div className="ml-3">
              <h3 className="text-sm font-medium text-red-800 dark:text-red-400">Error Loading Conditions</h3>
              <div className="mt-2 text-sm text-red-700 dark:text-red-300">
                <p>{error}</p>
              </div>
              <div className="mt-4">
                <button
                  onClick={loadAvailableConditions}
                  className="bg-red-100 dark:bg-red-900/40 px-3 py-1 rounded text-sm text-red-800 dark:text-red-400 hover:bg-red-200 dark:hover:bg-red-900/60"
                >
                  Retry
                </button>
              </div>
            </div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className={`space-y-4 ${className}`}>
      {/* Header */}
      <div className="flex justify-between items-center">
        <div>
          <h3 className="text-lg font-semibold text-gray-900 dark:text-white">
            Select Mental Health Conditions
          </h3>
          <p className="text-sm text-gray-600 dark:text-gray-400">
            Choose up to {maxSelections} conditions for assessment ({selectedConditions.length}/{maxSelections} selected)
          </p>
        </div>
        <div className="flex space-x-2">
          <button
            onClick={handleSelectAll}
            disabled={disabled || categorizedConditions.flatMap(c => c.conditions).length === 0}
            className="px-3 py-1 text-sm bg-blue-100 dark:bg-blue-900/40 text-blue-800 dark:text-blue-400 rounded hover:bg-blue-200 dark:hover:bg-blue-900/60 disabled:opacity-50 disabled:cursor-not-allowed"
          >
            Select All
          </button>
          <button
            onClick={handleClearAll}
            disabled={disabled || selectedConditions.length === 0}
            className="px-3 py-1 text-sm bg-gray-100 dark:bg-gray-700 text-gray-800 dark:text-gray-400 rounded hover:bg-gray-200 dark:hover:bg-gray-600 disabled:opacity-50 disabled:cursor-not-allowed"
          >
            Clear All
          </button>
        </div>
      </div>

      {/* Search and Filter Controls */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        <div>
          <label htmlFor="search" className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
            Search Conditions
          </label>
          <input
            id="search"
            type="text"
            placeholder="Search by name, description, or code..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            disabled={disabled}
            className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-md shadow-sm focus:ring-blue-500 focus:border-blue-500 dark:bg-gray-700 dark:text-white disabled:opacity-50 disabled:cursor-not-allowed"
          />
        </div>
        <div>
          <label htmlFor="category" className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
            Filter by Category
          </label>
          <select
            id="category"
            value={selectedCategory}
            onChange={(e) => setSelectedCategory(e.target.value)}
            disabled={disabled}
            className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-md shadow-sm focus:ring-blue-500 focus:border-blue-500 dark:bg-gray-700 dark:text-white disabled:opacity-50 disabled:cursor-not-allowed"
          >
            {getAvailableCategories().map(category => (
              <option key={category} value={category}>
                {category === 'all' ? 'All Categories' : category}
              </option>
            ))}
          </select>
        </div>
      </div>

      {/* Conditions List */}
      <div className="max-h-96 overflow-y-auto border border-gray-200 dark:border-gray-600 rounded-lg">
        {categorizedConditions.length === 0 ? (
          <div className="p-8 text-center text-gray-500 dark:text-gray-400">
            <svg className="mx-auto h-12 w-12 text-gray-400 mb-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" aria-hidden="true">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
            </svg>
            <p>No conditions found matching your criteria.</p>
            <p className="text-sm mt-1">Try adjusting your search or category filter.</p>
          </div>
        ) : (
          <div className="divide-y divide-gray-200 dark:divide-gray-600">
            {categorizedConditions.map(({ category, conditions }) => (
              <div key={category} className="bg-white dark:bg-gray-800">
                {/* Category Header */}
                <button
                  onClick={() => handleCategoryToggle(category)}
                  className="w-full px-4 py-3 text-left flex items-center justify-between bg-gray-50 dark:bg-gray-700 hover:bg-gray-100 dark:hover:bg-gray-600"
                >
                  <div>
                    <h4 className="font-medium text-gray-900 dark:text-white">{category}</h4>
                    <p className="text-sm text-gray-600 dark:text-gray-400">{conditions.length} conditions</p>
                  </div>
                  <svg
                    className={`h-5 w-5 text-gray-500 transform transition-transform ${
                      expandedCategories.has(category) ? 'rotate-90' : ''
                    }`}
                    viewBox="0 0 20 20"
                    fill="currentColor"
                    aria-hidden="true"
                  >
                    <path fillRule="evenodd" d="M7.293 14.707a1 1 0 010-1.414L10.586 10 7.293 6.707a1 1 0 011.414-1.414l4 4a1 1 0 010 1.414l-4 4a1 1 0 01-1.414 0z" clipRule="evenodd" />
                  </svg>
                </button>

                {/* Category Content */}
                {expandedCategories.has(category) && (
                  <div className="divide-y divide-gray-100 dark:divide-gray-700">
                    {conditions.map(condition => (
                      <label
                        key={condition.id}
                        className={`flex items-start p-4 cursor-pointer hover:bg-gray-50 dark:hover:bg-gray-700 ${
                          disabled ? 'opacity-50 cursor-not-allowed' : ''
                        }`}
                      >
                        <input
                          type="checkbox"
                          checked={selectedConditions.includes(condition.id)}
                          onChange={() => handleConditionToggle(condition.id)}
                          disabled={disabled || (!selectedConditions.includes(condition.id) && selectedConditions.length >= maxSelections)}
                          className="mt-1 h-4 w-4 text-blue-600 focus:ring-blue-500 border-gray-300 dark:border-gray-600 rounded disabled:opacity-50 disabled:cursor-not-allowed"
                        />
                        <div className="ml-3 flex-1 min-w-0">
                          <div className="flex items-center justify-between">
                            <p className="text-sm font-medium text-gray-900 dark:text-white">
                              {condition.name}
                            </p>
                            <span className="ml-2 px-2 py-1 text-xs bg-gray-100 dark:bg-gray-600 text-gray-600 dark:text-gray-300 rounded">
                              {condition.code}
                            </span>
                          </div>
                          {condition.description && (
                            <p className="mt-1 text-sm text-gray-600 dark:text-gray-400 line-clamp-2">
                              {condition.description}
                            </p>
                          )}
                          <div className="mt-2 flex items-center text-xs text-gray-500 dark:text-gray-400">
                            <span>Criteria: {condition.criteriaCount || 0}</span>
                            {condition.pageNumbers && condition.pageNumbers.length > 0 && (
                              <>
                                <span className="mx-2">•</span>
                                <span>Pages: {condition.pageNumbers.join(', ')}</span>
                              </>
                            )}
                          </div>
                        </div>
                      </label>
                    ))}
                  </div>
                )}
              </div>
            ))}
          </div>
        )}
      </div>

      {/* Selection Summary */}
      {selectedConditions.length > 0 && (
        <div className="p-4 bg-blue-50 dark:bg-blue-900/20 border border-blue-200 dark:border-blue-800 rounded-lg">
          <h4 className="text-sm font-medium text-blue-900 dark:text-blue-400 mb-2">
            Selected Conditions ({selectedConditions.length})
          </h4>
          <div className="flex flex-wrap gap-2">
            {selectedConditions.map(conditionId => {
              const condition = availableConditions.find(c => c.id === conditionId);
              return condition ? (
                <span
                  key={conditionId}
                  className="inline-flex items-center px-2 py-1 rounded-full text-xs font-medium bg-blue-100 dark:bg-blue-900/40 text-blue-800 dark:text-blue-400"
                >
                  {condition.name}
                  {!disabled && (
                    <button
                      onClick={() => handleConditionToggle(conditionId)}
                      className="ml-1 inline-flex items-center justify-center w-4 h-4 rounded-full text-blue-600 dark:text-blue-400 hover:bg-blue-200 dark:hover:bg-blue-800"
                    >
                      ×
                    </button>
                  )}
                </span>
              ) : null;
            })}
          </div>
        </div>
      )}
    </div>
  );
};

/**
 * Extended Risk Assessment Button Component
 * Provides UI for triggering and displaying extended risk assessments with schizophrenia evaluation
 * Uses async job pattern to handle long-running GPT-5/O3 calls without timeout issues
 */

import React, { useState, useEffect, useRef } from 'react';
import { Brain, Loader2, AlertCircle, RefreshCw, Clock } from 'lucide-react';
import { ExtendedRiskAssessmentDisplay } from './ExtendedRiskAssessmentDisplay';
import {
  ExtendedRiskAssessment,
  ExtendedRiskAssessmentResponse,
  ExtendedRiskAssessmentStatusResponse
} from '../types/extendedRiskAssessment';
import { apiPost, apiGet } from '../utils/api';
import { config } from '../config/constants';
import { Logger } from '@/utils/logger';

const log = Logger.create('ExtendedRiskAssessment');

// Job-related types
interface ExtendedAssessmentJob {
  jobId: string;
  sessionId: string;
  status: 'pending' | 'processing' | 'completed' | 'failed' | 'cancelled' | 'timedout';
  progressPercentage: number;
  currentStep?: string;
  createdAt: string;
  startedAt?: string;
  completedAt?: string;
  processingTimeMs?: number;
  elapsedTimeMs: number;
  isCompleted: boolean;
  isProcessing: boolean;
  errorMessage?: string;
  modelUsed?: string;
  retryCount: number;
  canRetry: boolean;
}

interface JobStatusResponse {
  success: boolean;
  job: ExtendedAssessmentJob;
  message?: string;
  error?: string;
}

interface StartJobResponse {
  success: boolean;
  message: string;
  jobId: string;
  instanceId: string;
  sessionId: string;
  statusUrl: string;
  resultUrl: string;
  estimatedProcessingTime: string;
  error?: string;
}

interface ExtendedRiskAssessmentButtonProps {
  sessionId: string;
  apiBaseUrl: string;
  existingAssessment?: ExtendedRiskAssessment | null;
  selectedDSM5Conditions?: string[];
  onStart?: () => void;
  onComplete?: (assessment: ExtendedRiskAssessment) => void;
  onError?: (error: string) => void;
}

export const ExtendedRiskAssessmentButton: React.FC<ExtendedRiskAssessmentButtonProps> = ({
  sessionId,
  apiBaseUrl,
  existingAssessment,
  selectedDSM5Conditions = [],
  onStart,
  onComplete,
  onError
}) => {
  const [isLoading, setIsLoading] = useState(false);
  const [isChecking, setIsChecking] = useState(false);
  const [assessment, setAssessment] = useState<ExtendedRiskAssessment | null>(existingAssessment || null);
  const [status, setStatus] = useState<ExtendedRiskAssessmentStatusResponse | null>(null);
  const [error, setError] = useState<string | null>(null);

  // Job-related state
  const [currentJob, setCurrentJob] = useState<ExtendedAssessmentJob | null>(null);
  const [jobProgress, setJobProgress] = useState(0);
  const [jobStep, setJobStep] = useState<string>('');
  const [processingStartTime, setProcessingStartTime] = useState<Date | null>(null);
  const [elapsedTime, setElapsedTime] = useState(0);

  // Refs for cleanup
  const pollingIntervalRef = useRef<NodeJS.Timeout | null>(null);
  const elapsedTimeIntervalRef = useRef<NodeJS.Timeout | null>(null);

  // Cleanup effect
  useEffect(() => {
    return () => {
      if (pollingIntervalRef.current) {
        clearInterval(pollingIntervalRef.current);
      }
      if (elapsedTimeIntervalRef.current) {
        clearInterval(elapsedTimeIntervalRef.current);
      }
    };
  }, []);

  // Load existing assessment on mount or when it changes
  useEffect(() => {
    log.debug('Component mounted for session:', { sessionId });
    log.debug('existingAssessment prop:', { existingAssessment });

    if (existingAssessment) {
      log.info('Existing assessment provided, displaying immediately');
      setAssessment(existingAssessment);
    } else {
      log.debug('No existing assessment, checking API...');
      // Check if assessment exists on the server
      fetchAssessment();
    }
  }, [sessionId, existingAssessment]);

  // Check status of extended risk assessment
  const checkStatus = async () => {
    log.debug('Checking status for session:', { sessionId });
    setIsChecking(true);
    setError(null);

    try {
      const response = await apiGet<ExtendedRiskAssessmentStatusResponse>(
        `${apiBaseUrl}/sessions/${sessionId}/extended-risk-assessment/status`
      );

      log.debug('Status response:', response);

      if (response.success && response.data) {
        // Parse data if it's a string (sometimes API returns stringified JSON)
        const parsedData = typeof response.data === 'string'
          ? JSON.parse(response.data)
          : response.data;

        log.debug('Status check successful', { data: parsedData });
        setStatus(parsedData);

        // If assessment exists, fetch it
        if (response.data.hasExtendedAssessment) {
          await fetchAssessment();
        }
      } else {
        setError(response.error || 'Failed to check assessment status');
        onError?.(response.error || 'Failed to check assessment status');
      }
    } catch (err) {
      const errorMsg = err instanceof Error ? err.message : 'Unknown error checking status';
      setError(errorMsg);
      onError?.(errorMsg);
    } finally {
      setIsChecking(false);
    }
  };

  // Fetch existing assessment
  const fetchAssessment = async () => {
    log.debug('Fetching existing assessment for session:', { sessionId });
    try {
      const response = await apiGet<ExtendedRiskAssessmentResponse>(
        `${apiBaseUrl}/sessions/${sessionId}/extended-risk-assessment`
      );

      log.debug('Fetch response:', response);

      // Check both wrapper success and inner API response success
      if (response.success && response.data) {
        // Parse data if it's a string (sometimes API returns stringified JSON)
        const parsedData = typeof response.data === 'string'
          ? JSON.parse(response.data)
          : response.data;

        log.debug('Wrapper success: true, checking inner response...', { success: parsedData.success, hasAssessment: !!parsedData.extendedRiskAssessment });

        if (parsedData.success && parsedData.extendedRiskAssessment) {
          log.info('Assessment fetched successfully');
          setAssessment(parsedData.extendedRiskAssessment);
          setIsLoading(false); // Make sure to stop loading when we get the result
          onComplete?.(parsedData.extendedRiskAssessment);
        } else if (parsedData.success && parsedData.hasExtendedAssessment === false) {
          log.info('No assessment generated yet for this session');
        } else {
          log.warn('Inner response missing success or extendedRiskAssessment');
        }
      } else {
        log.warn('Wrapper response failed or no data');
      }
    } catch (err) {
      log.error('Error fetching assessment', err);
    }
  };

  // Start async job for assessment generation
  const generateAssessment = async () => {
    log.info('Starting async job for session:', { sessionId });

    // Call onStart callback to notify parent component
    onStart?.();

    setIsLoading(true);
    setError(null);
    setCurrentJob(null);
    setJobProgress(0);
    setJobStep('');
    setElapsedTime(0);

    // Clear existing assessment when regenerating to show loading state
    if (assessment) {
      log.debug('Clearing existing assessment for regeneration');
      setAssessment(null);
    }

    try {
      log.debug('Making POST request to start async job...');
      log.debug('Selected DSM-5 conditions:', { selectedDSM5Conditions });
      const response = await apiPost<StartJobResponse>(
        `${apiBaseUrl}/sessions/${sessionId}/extended-risk-assessment`,
        {
          selectedConditions: selectedDSM5Conditions.length > 0 ? selectedDSM5Conditions : []
        }
      );

      log.debug('Job start response:', response);

      if (response.success && response.data) {
        // Parse the JSON string response
        const jobData = typeof response.data === 'string' ? JSON.parse(response.data) : response.data;
        log.info('Job started successfully!', { jobId: jobData.jobId });

        setJobStep('Job created, starting processing...');
        setProcessingStartTime(new Date());

        // Start polling for job status
        startJobPolling(jobData.jobId);
      } else {
        log.error('Failed to start job');
        const errorMsg = response.error || 'Failed to start assessment job';
        setError(errorMsg);
        onError?.(errorMsg);
        setIsLoading(false);
      }
    } catch (err) {
      log.error('Exception starting job', err);
      const errorMsg = err instanceof Error ? err.message : 'Unknown error starting assessment job';
      setError(errorMsg);
      onError?.(errorMsg);
      setIsLoading(false);
    }
  };

  // Start polling for job completion
  const startJobPolling = (jobId: string) => {
    log.debug('Starting job polling for:', { jobId });

    // Start elapsed time counter
    elapsedTimeIntervalRef.current = setInterval(() => {
      if (processingStartTime) {
        const elapsed = Math.floor((Date.now() - processingStartTime.getTime()) / 1000);
        setElapsedTime(elapsed);
      }
    }, 1000);

    // Poll job status at configurable interval (default 5 seconds)
    const pollJob = async () => {
      try {
        const response = await apiGet<JobStatusResponse>(
          `${apiBaseUrl}/jobs/${jobId}`
        );

        // Parse response.data if it's a string
        const jobData = typeof response.data === 'string' ? JSON.parse(response.data) : response.data;

        if (response.success && jobData?.job) {
          const job = jobData.job;
          setCurrentJob(job);
          setJobProgress(job.progressPercentage);
          setJobStep(job.currentStep || '');

          log.debug('Job status:', { status: job.status, progress: job.progressPercentage, step: job.currentStep });

          if (job.isCompleted) {
            log.info('Job completed!');
            stopJobPolling();

            if (job.status === 'completed') {
              // Job completed successfully, fetch the result
              await fetchAssessment();
            } else {
              // Job failed
              const errorMsg = job.errorMessage || 'Assessment job failed';
              setError(errorMsg);
              onError?.(errorMsg);
              setIsLoading(false);
            }
          }
        } else {
          log.error('Failed to get job status');
        }
      } catch (err) {
        log.error('Error polling job', err);
      }
    };

    // Poll immediately and then every configurable interval (default 5 seconds)
    pollJob();
    pollingIntervalRef.current = setInterval(pollJob, config.polling.jobIntervalMs);
  };

  // Stop job polling
  const stopJobPolling = () => {
    log.debug('Stopping job polling');

    if (pollingIntervalRef.current) {
      clearInterval(pollingIntervalRef.current);
      pollingIntervalRef.current = null;
    }

    if (elapsedTimeIntervalRef.current) {
      clearInterval(elapsedTimeIntervalRef.current);
      elapsedTimeIntervalRef.current = null;
    }
  };

  // Format elapsed time
  const formatElapsedTime = (seconds: number): string => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  // Get descriptive stage info based on progress percentage
  const getProgressStages = (progress: number) => {
    const stages = [
      { label: 'Validating session data', threshold: 10, icon: '🔍' },
      { label: 'Preparing clinical prompt', threshold: 30, icon: '📋' },
      { label: 'Sending to AI model', threshold: 40, icon: '🚀' },
      { label: 'AI model generating assessment', threshold: 50, icon: '🧠' },
      { label: 'Parsing AI response', threshold: 80, icon: '📊' },
      { label: 'Saving assessment results', threshold: 90, icon: '💾' },
      { label: 'Finalizing', threshold: 100, icon: '✅' },
    ];
    return stages.map(stage => ({
      ...stage,
      status: progress >= stage.threshold ? 'completed' as const
        : progress >= stage.threshold - 10 ? 'active' as const
        : 'pending' as const,
    }));
  };

  // If no assessment exists and not generating/checking, show generate buttons (matching RiskAssessment component)
  if (!assessment && !isLoading && !isChecking) {
    return (
      <div className="bg-white dark:bg-gray-800 rounded-lg border border-gray-200 dark:border-gray-700 p-6">
        <h2 className="text-xl font-semibold text-gray-900 dark:text-white mb-4 flex items-center">
          <Brain className="w-5 h-5 mr-2" aria-hidden="true" />
          AI Risk Assessment (Extended)
        </h2>

        <div className="text-center py-8">
          <Brain className="w-12 h-12 text-gray-400 mx-auto mb-4" aria-hidden="true" />
          <h3 className="text-lg font-medium text-gray-900 dark:text-white mb-2">
            No Extended Risk Assessment Available
          </h3>
          <p className="text-gray-600 dark:text-gray-300 mb-6">
            {selectedDSM5Conditions.length > 0 ? (
              selectedDSM5Conditions.length === 1 ? (
                `Generate an AI-powered extended risk assessment with comprehensive DSM-5 evaluation for the selected condition using GPT-5/O3. Processing time: 30-120 seconds.`
              ) : (
                `Generate an AI-powered extended risk assessment with comprehensive DSM-5 evaluation for ${selectedDSM5Conditions.length} selected conditions using GPT-5/O3. Processing time: 30-120 seconds.`
              )
            ) : (
              'Generate an AI-powered extended risk assessment with comprehensive DSM-5 schizophrenia evaluation using GPT-5/O3. Processing time: 30-120 seconds.'
            )}
          </p>

          <div className="space-y-3">
            <button type="button"
              onClick={generateAssessment}
              disabled={status?.canGenerate === false}
              className="btn btn--primary"
              aria-label="Generate extended AI risk assessment"
            >
              <Brain className="w-4 h-4 mr-2" aria-hidden="true" />
              Generate Extended Risk Assessment
            </button>

            <button type="button"
              onClick={checkStatus}
              className="btn btn--secondary"
              aria-label="Check for existing extended assessment"
            >
              <RefreshCw className="w-4 h-4 mr-2" aria-hidden="true" />
              Check for Existing Assessment
            </button>
          </div>

          {/* Status Info */}
          {status && (
            <div className="mt-6 bg-gray-50 dark:bg-gray-700 rounded-lg p-4 text-sm">
              <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
                <div>
                  <span className="text-gray-600 dark:text-gray-400 block mb-1">Standard Assessment:</span>
                  <span className={`font-medium ${status.hasStandardAssessment ? 'text-green-600 dark:text-green-400' : 'text-gray-500'}`}>
                    {status.hasStandardAssessment ? '✓ Available' : '✗ Not Available'}
                  </span>
                </div>
                <div>
                  <span className="text-gray-600 dark:text-gray-400 block mb-1">Audio Transcription:</span>
                  <span className={`font-medium ${status.hasTranscription ? 'text-green-600 dark:text-green-400' : 'text-gray-500'}`}>
                    {status.hasTranscription ? '✓ Available' : '✗ Not Available'}
                  </span>
                </div>
                <div>
                  <span className="text-gray-600 dark:text-gray-400 block mb-1">Can Generate:</span>
                  <span className={`font-medium ${status.canGenerate ? 'text-green-600 dark:text-green-400' : 'text-red-600 dark:text-red-400'}`}>
                    {status.canGenerate ? '✓ Yes' : '✗ Prediction Required'}
                  </span>
                </div>
              </div>
            </div>
          )}

          {/* Error Display */}
          {error && (
            <div role="alert" className="mt-4 p-3 bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-lg">
              <p className="text-red-700 dark:text-red-300 text-sm flex items-center justify-center">
                <AlertCircle className="w-4 h-4 mr-2" aria-hidden="true" />
                {error}
              </p>
            </div>
          )}
        </div>
      </div>
    );
  }

  // Loading state with job progress
  if (isLoading || isChecking) {
    const stages = getProgressStages(jobProgress);
    return (
      <div className="bg-white dark:bg-gray-800 rounded-lg border border-gray-200 dark:border-gray-700 p-6">
        <h2 className="text-xl font-semibold text-gray-900 dark:text-white mb-4 flex items-center">
          <Brain className="w-5 h-5 mr-2" aria-hidden="true" />
          AI Risk Assessment (Extended)
        </h2>

        <div className="py-6">
          {/* Header with spinner */}
          <div className="text-center mb-6">
            <Loader2 className="w-10 h-10 text-blue-600 mx-auto mb-3 animate-spin" aria-hidden="true" />
            <h3 className="text-lg font-medium text-gray-900 dark:text-white">
              {isLoading ? 'Generating Extended Assessment' : 'Checking Status...'}
            </h3>
          </div>

          {/* Progress Bar */}
          {isLoading && currentJob && (
            <div className="max-w-lg mx-auto space-y-4">
              <div className="flex justify-between items-center text-sm text-gray-600 dark:text-gray-300 mb-1">
                <span className="font-medium">Progress</span>
                <span className="font-semibold text-blue-600 dark:text-blue-400">{jobProgress}%</span>
              </div>
              <div
                className="bg-gray-200 dark:bg-gray-700 rounded-full h-2.5"
                role="progressbar"
                aria-valuenow={jobProgress}
                aria-valuemin={0}
                aria-valuemax={100}
                aria-label={`Assessment progress: ${jobProgress}%`}
              >
                <div
                  className="bg-gradient-to-r from-blue-500 to-blue-600 h-2.5 rounded-full transition-all duration-500 ease-out"
                  style={{'--progress-width': `${jobProgress}%`, width: 'var(--progress-width)'} as React.CSSProperties}
                  aria-hidden="true"
                ></div>
              </div>

              {/* Stage List */}
              <div className="mt-5 space-y-2">
                {stages.map((stage) => (
                  <div
                    key={stage.label}
                    className={`flex items-center gap-3 px-3 py-1.5 rounded-md text-sm transition-all duration-300 ${
                      stage.status === 'completed'
                        ? 'text-green-700 dark:text-green-400 bg-green-50 dark:bg-green-900/20'
                        : stage.status === 'active'
                        ? 'text-blue-700 dark:text-blue-300 bg-blue-50 dark:bg-blue-900/20 font-medium'
                        : 'text-gray-400 dark:text-gray-500'
                    }`}
                  >
                    <span className="w-5 text-center flex-shrink-0">
                      {stage.status === 'completed' ? '✓' : stage.status === 'active' ? stage.icon : '○'}
                    </span>
                    <span className={stage.status === 'active' ? 'animate-pulse' : ''}>
                      {stage.label}
                      {stage.status === 'active' && '...'}
                    </span>
                    {stage.status === 'active' && (
                      <Loader2 className="w-3.5 h-3.5 animate-spin ml-auto flex-shrink-0" />
                    )}
                  </div>
                ))}
              </div>

              {/* Current Step Detail (from backend) */}
              {jobStep && (
                <div className="mt-4 px-3 py-2 bg-gray-50 dark:bg-gray-700/50 rounded-md">
                  <p className="text-xs text-gray-500 dark:text-gray-400 font-medium mb-0.5">Current Step:</p>
                  <p className="text-sm text-gray-700 dark:text-gray-300">{jobStep}</p>
                </div>
              )}

              {/* Elapsed Time */}
              {elapsedTime > 0 && (
                <div className="flex justify-between items-center text-xs text-gray-500 dark:text-gray-400 mt-3 px-1">
                  <span className="flex items-center gap-1">
                    <Clock className="w-3.5 h-3.5" />
                    Elapsed: {formatElapsedTime(elapsedTime)}
                  </span>
                  {jobProgress >= 40 && jobProgress < 80 && (
                    <span className="italic">
                      AI model is thinking — this can take 1-3 min in air-gap mode
                    </span>
                  )}
                </div>
              )}
            </div>
          )}
        </div>
      </div>
    );
  }

  // Assessment display (matching RiskAssessment component)
  if (assessment) {
    return (
      <div className="bg-white dark:bg-gray-800 rounded-lg border border-gray-200 dark:border-gray-700 p-6">
        <div className="flex items-center justify-between mb-4">
          <h2 className="text-xl font-semibold text-gray-900 dark:text-white flex items-center">
            <Brain className="w-5 h-5 mr-2" aria-hidden="true" />
            AI Risk Assessment (Extended)
          </h2>
          <button type="button"
            onClick={() => {
              log.debug('Regenerate button clicked - stopping polling and calling generateAssessment()');
              stopJobPolling();
              generateAssessment();
            }}
            disabled={isLoading}
            className="btn btn--secondary text-sm"
            aria-label="Regenerate extended assessment"
          >
            <RefreshCw className="w-4 h-4 mr-2" aria-hidden="true" />
            Regenerate
          </button>
        </div>

        {assessment && <ExtendedRiskAssessmentDisplay assessment={assessment} />}
      </div>
    );
  }

  return null;
};

