  const handleCsvFileSelect = useCallback((event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    if (!file.name.toLowerCase().endsWith('.csv')) {
      setCsvValidationErrors(['Please select a valid CSV file']);
      return;
    }

    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const csvText = e.target?.result as string;
        const rows = csvText.split('\n').filter(row => row.trim());

        if (rows.length < 2) {
          setCsvValidationErrors(['CSV must contain at least a header row and one data row']);
          return;
        }

        // Proper CSV parsing function that handles quoted values and commas
        const parseCsvRow = (row: string): string[] => {
          const result: string[] = [];
          let current = '';
          let inQuotes = false;
          let i = 0;

          while (i < row.length) {
            const char = row[i];
            const nextChar = row[i + 1];

            if (char === '"' && !inQuotes) {
              // Start of quoted field
              inQuotes = true;
            } else if (char === '"' && inQuotes) {
              if (nextChar === '"') {
                // Escaped quote inside quoted field
                current += '"';
                i++; // Skip next quote
              } else {
                // End of quoted field
                inQuotes = false;
              }
            } else if (char === ',' && !inQuotes) {
              // Field separator outside quotes
              result.push(current.trim());
              current = '';
            } else {
              // Regular character
              current += char;
            }
            i++;
          }

          // Add the last field
          result.push(current.trim());
          return result;
        };

        const headers = parseCsvRow(rows[0]).map(h => h.replace(/^"|"$/g, '').trim());
        const requiredHeaders = ['userId', 'fileName'];
        const optionalHeaders = ['age', 'gender', 'race', 'ethnicity', 'language', 'weight', 'zipcode', 'sessionNotes'];

        const missingHeaders = requiredHeaders.filter(h => !headers.includes(h));
        if (missingHeaders.length > 0) {
          setCsvValidationErrors([`Missing required columns: ${missingHeaders.join(', ')}`]);
          return;
        }

        const parsedRows: CsvBatchRow[] = [];
        const errors: string[] = [];

        for (let i = 1; i < rows.length; i++) {
          const values = parseCsvRow(rows[i]).map(v => v.replace(/^"|"$/g, '').trim());
          const row: CsvBatchRow = { userId: '', fileName: '' };

          headers.forEach((header, index) => {
            const value = values[index] || '';
            if (header === 'userId' || header === 'fileName') {
              (row as any)[header] = value;
            } else if (optionalHeaders.includes(header)) {
              (row as any)[header] = value;
            }
          });

          // Basic required field validation
          if (!row.userId || !row.fileName) {
            errors.push(`Row ${i + 1}: Missing required values for userId or fileName`);
          } else {
            // Validate optional fields that have specific requirements
            let hasFieldErrors = false;

            // Validate ethnicity format
            if (row.ethnicity && row.ethnicity.trim()) {
              const validEthnicities = [
                "hispanic, latino, or spanish origin",
                "not hispanic, latino, or spanish origin"
              ];
              const normalizedEthnicity = row.ethnicity.toLowerCase().trim();
              if (!validEthnicities.includes(normalizedEthnicity)) {
                errors.push(`Row ${i + 1}: Invalid ethnicity "${row.ethnicity}". Must be: "Hispanic, Latino, or Spanish Origin" or "Not Hispanic, Latino, or Spanish Origin"`);
                hasFieldErrors = true;
              }
            }

            // Validate weight range
            if (row.weight && row.weight.trim()) {
              const weightNum = parseInt(row.weight.trim());
              if (isNaN(weightNum) || weightNum < 10 || weightNum > 1000) {
                errors.push(`Row ${i + 1}: Weight must be between 10 and 1000 pounds, got "${row.weight}"`);
                hasFieldErrors = true;
              }
            }

            // Validate age range
            if (row.age && row.age.trim()) {
              const ageNum = parseInt(row.age.trim());
              if (isNaN(ageNum) || ageNum < 1 || ageNum > 149) {
                errors.push(`Row ${i + 1}: Age must be between 1 and 149 years, got "${row.age}"`);
                hasFieldErrors = true;
              }
            }

            // Validate gender options
            if (row.gender && row.gender.trim()) {
              const validGenders = ["female", "male", "non-binary", "transgender female", "transgender male", "other", "prefer not to say"];
              if (!validGenders.includes(row.gender.toLowerCase().trim())) {
                errors.push(`Row ${i + 1}: Invalid gender "${row.gender}". Must be one of: ${validGenders.join(', ')}`);
                hasFieldErrors = true;
              }
            }

            // Validate race options
            if (row.race && row.race.trim()) {
              const validRaces = [
                "white",
                "black or african-american",
                "asian",
                "american indian or alaskan native",
                "native Hawaiian or pacific islander",
                "two or more races",
                "other",
                "prefer not to say"
              ];
              const normalizedInputRace = row.race.toLowerCase().trim();
              if (!validRaces.includes(normalizedInputRace)) {
                errors.push(`Row ${i + 1}: Invalid race "${row.race}". Must be one of: ${validRaces.join(', ')}`);
                hasFieldErrors = true;
              }
            }

            // Validate zipcode format
            if (row.zipcode && row.zipcode.trim()) {
              if (!/^[0-9]{5}$/.test(row.zipcode.trim())) {
                errors.push(`Row ${i + 1}: Zipcode must be exactly 5 digits, got "${row.zipcode}"`);
                hasFieldErrors = true;
              }
            }

            // Validate language
            if (row.language !== undefined && row.language !== null) {
              if (typeof row.language === 'string') {
                const langValue = (row.language as string).toLowerCase().trim();
                if (!['true', 'false'].includes(langValue)) {
                  errors.push(`Row ${i + 1}: Language must be boolean (true/false), got "${row.language}"`);
                  hasFieldErrors = true;
                }
              } else if (typeof row.language !== 'boolean') {
                errors.push(`Row ${i + 1}: Language must be boolean, got ${typeof row.language}`);
                hasFieldErrors = true;
              }
            }

            // Validate sessionNotes length (optional but reasonable limit)
            if (row.sessionNotes && row.sessionNotes.trim()) {
              if (row.sessionNotes.trim().length > 500) {
                errors.push(`Row ${i + 1}: Session notes must be 500 characters or less, got ${row.sessionNotes.trim().length} characters`);
                hasFieldErrors = true;
              }
            }

            // Validate fileName format (optional but should be reasonable)
            if (row.fileName && row.fileName.trim()) {
              if (row.fileName.trim().length > 255) {
                errors.push(`Row ${i + 1}: File name must be 255 characters or less, got ${row.fileName.trim().length} characters`);
                hasFieldErrors = true;
              }
              // Check for potentially problematic characters in filename
              const invalidChars = /[<>:"/\\|?*\x00-\x1f]/;
              if (invalidChars.test(row.fileName.trim())) {
                errors.push(`Row ${i + 1}: File name contains invalid characters, got "${row.fileName}"`);
                hasFieldErrors = true;
              }
            }

            if (!hasFieldErrors) {
              parsedRows.push(row);
            }
          }
        }

        if (errors.length > 0) {
          setCsvValidationErrors(errors);
          return;
        }

        setCsvBatchData({ rows: parsedRows, fileName: file.name });
        setCsvValidationErrors([]);
        // Clear audio files when new CSV is uploaded so the load button can be re-enabled
        setAudioFiles([]);
        announceToScreenReader(`CSV file loaded with ${parsedRows.length} valid rows`);
      } catch (error) {
        setCsvValidationErrors(['Error parsing CSV file. Please check file format.']);
      }
    };

    reader.readAsText(file);
  }, [announceToScreenReader]);

  // Handle folder selection for CSV batch mode
  const handleFolderSelect = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files || files.length === 0) {
      setCsvFolderFiles([]);
      return;
    }

    // Filter for audio/video files only
    const audioExtensions = ['.wav', '.mp3', '.m4a', '.aac', '.flac', '.mp4', '.webm', '.ogg', '.mov'];
    const audioFiles = Array.from(files).filter(file => {
      const ext = file.name.toLowerCase().substring(file.name.lastIndexOf('.'));
      return audioExtensions.includes(ext);
    });

    setCsvFolderFiles(audioFiles);
    addToast('success', 'Folder Selected', `Found ${audioFiles.length} audio/video file(s) in selected folder`);
    announceToScreenReader(`Selected folder contains ${audioFiles.length} audio files`);
  }, [addToast, announceToScreenReader]);

  const processCsvBatch = useCallback(async () => {
    if (!csvBatchData) return;
    if (csvFolderFiles.length === 0) {
      addToast('error', 'No Folder Selected', 'Please select a folder containing audio files first.');
      return;
    }

    const totalRows = csvBatchData.rows.length;

    // Initialize row results
    const initialResults: CsvRowResult[] = csvBatchData.rows.map((row, index) => ({
      rowIndex: index,
      fileName: row.fileName,
      userId: row.userId,
      status: 'pending' as const
    }));
    setCsvRowResults(initialResults);

    setCsvProcessingProgress({
      isProcessing: true,
      currentFile: 0,
      totalFiles: totalRows,
      currentFileName: '',
      message: 'Starting CSV batch processing...'
    });

    // Build a map of folder files by name for quick lookup
    const folderFilesMap = new Map<string, File>();
    csvFolderFiles.forEach(file => {
      folderFilesMap.set(file.name.toLowerCase(), file);
    });

    let successCount = 0;
    let errorCount = 0;

    for (let i = 0; i < csvBatchData.rows.length; i++) {
      const row = csvBatchData.rows[i];
      const filename = row.fileName;

      // Update progress
      setCsvProcessingProgress(prev => ({
        ...prev,
        currentFile: i + 1,
        currentFileName: filename,
        message: `Processing ${i + 1} of ${totalRows}: ${filename}`
      }));

      // Update row status to processing
      setCsvRowResults(prev => prev.map((r, idx) =>
        idx === i ? { ...r, status: 'processing' as const } : r
      ));

      try {
        // Find matching file in folder (case-insensitive)
        const matchedFile = folderFilesMap.get(filename.toLowerCase());

        if (!matchedFile) {
          throw new Error(`File "${filename}" not found in selected folder`);
        }

        // Create metadata from CSV row
        const metadata: UserMetadata = {
          userId: row.userId,
          age: row.age,
          gender: row.gender,
          race: row.race,
          ethnicity: row.ethnicity ? normalizeEthnicityForBackend(row.ethnicity) : row.ethnicity,
          language: row.language,
          weight: row.weight,
          zipcode: row.zipcode,
          sessionNotes: row.sessionNotes
        };

        // Step 1: Initiate session
        setCsvProcessingProgress(prev => ({
          ...prev,
          message: `Row ${i + 1}: Initiating session...`
        }));

        const sessionRequest: any = {
          userid: row.userId.trim(),
          is_initiated: true
        };

        const builtMetadata = buildMetadataFromUserData(metadata);
        if (builtMetadata) {
          sessionRequest.metadata = builtMetadata;
        }

        const sessionResponse = await apiService.initiateSession(sessionRequest);
        const sessionId = sessionResponse.sessionId;

        // Save initial session data
        const initialSessionData = {
          sessionId: sessionId,
          userId: getAuthenticatedUserId(),
          metadata_user_id: row.userId.trim(),
          groupId: selectedGroupId,
          ...(builtMetadata && { userMetadata: builtMetadata }),
          audioFileName: matchedFile.name,
          createdAt: new Date().toISOString(),
          updatedAt: new Date().toISOString(),
          status: 'initiated'
        };

        try {
          await apiService.saveSessionData(initialSessionData);
        } catch (saveError) {
          log.warn('Failed to save initial session data', { error: saveError });
        }

        // Step 2: Convert audio
        setCsvProcessingProgress(prev => ({
          ...prev,
          message: `Row ${i + 1}: Converting audio...`
        }));

        const convertedBlob = await convertAudioToWav(matchedFile);

        // Step 3: Upload to Azure Blob Storage
        setCsvProcessingProgress(prev => ({
          ...prev,
          message: `Row ${i + 1}: Uploading audio...`
        }));

        const blobFileName = `${row.userId}_${sessionId}_${Date.now()}.wav`;
        const audioUrl = await uploadToAzureBlob(
          convertedBlob,
          blobFileName,
          undefined,
          getAuthenticatedUserId()
        );

        // Update session with audio URL
        try {
          await apiService.updateSessionData(sessionId, {
            ...initialSessionData,
            audioUrl: audioUrl,
            audioFileName: blobFileName,
            status: 'processing',
            updatedAt: new Date().toISOString()
          });
        } catch (updateError) {
          log.warn('Failed to update session with audio URL', { error: updateError });
        }

        // Step 4: Transcribe audio (if enabled)
        let transcriptionText: string | null = null;
        const effectiveTranscribeAudio = transcribeAudio && isTranscriptionEnabled;

        if (effectiveTranscribeAudio) {
          setCsvProcessingProgress(prev => ({
            ...prev,
            message: `Row ${i + 1}: Transcribing audio...`
          }));

          try {
            const transcriptionResult = await transcriptionService.transcribeAudio(convertedBlob);
            if (!transcriptionResult.error) {
              transcriptionText = transcriptionResult.text;
              await apiService.saveTranscription(sessionId, transcriptionText);
            }
          } catch (transcriptionError) {
            log.warn('Transcription failed for row', { row: i + 1, error: transcriptionError });
          }
        }

        // Step 5: Save final results
        const finalSessionData = {
          ...initialSessionData,
          audioUrl: audioUrl,
          transcription: transcriptionText || undefined,
          analysisResults: {
            riskLevel: 'unknown',
            insights: ['Batch processing completed'],
            transcriptionText: transcriptionText || undefined,
            completedAt: new Date().toISOString()
          },
          status: 'completed',
          completedAt: new Date().toISOString(),
          updatedAt: new Date().toISOString()
        };

        await apiService.saveSessionData(finalSessionData);

        // Update row result as success
        setCsvRowResults(prev => prev.map((r, idx) =>
          idx === i ? {
            ...r,
            status: 'success' as const,
            sessionId: sessionId
          } : r
        ));

        successCount++;
        addToast('success', 'Row Processed', `Successfully processed ${filename}`);

      } catch (error) {
        log.error(`Error processing CSV row ${i + 1}`, error);

        // Update row result as error
        setCsvRowResults(prev => prev.map((r, idx) =>
          idx === i ? {
            ...r,
            status: 'error' as const,
            error: error instanceof Error ? error.message : 'Unknown error'
          } : r
        ));

        errorCount++;
        addToast('error', 'Row Failed', `Failed to process ${filename}: ${error instanceof Error ? error.message : 'Unknown error'}`);
        // Continue with next row
      }

      // Small delay between rows to prevent overwhelming the system
      await new Promise(resolve => setTimeout(resolve, 500));
    }

    // Final summary
    setCsvProcessingProgress(prev => ({
      ...prev,
      message: `Complete: ${successCount} succeeded, ${errorCount} failed`
    }));

    if (successCount > 0) {
      addToast('success', 'CSV Batch Complete', `Successfully processed ${successCount} of ${totalRows} files`);
    }
    if (errorCount > 0) {
      addToast('warning', 'Some Rows Failed', `${errorCount} of ${totalRows} files failed to process. Check results below.`);
    }

    announceToScreenReader(`CSV batch processing complete. ${successCount} succeeded, ${errorCount} failed.`);

    // Keep progress visible (don't auto-hide)
    setCsvProcessingProgress(prev => ({
      ...prev,
      isProcessing: false
    }));
  }, [csvBatchData, csvFolderFiles, addToast, announceToScreenReader, transcribeAudio, isTranscriptionEnabled, selectedGroupId]);

  const handleFileSelect = useCallback((event: React.ChangeEvent<HTMLInputElement>) => {
    const files = event.target.files;
    if (!files || files.length === 0) return;

    // Process multiple files or single file
    Array.from(files).forEach(file => {
      // Validate file type - check both MIME type and file extension
      const supportedMimeTypes = [
        'audio/wav', 'audio/wave', 'audio/x-wav',
        'audio/mp3', 'audio/mpeg', 'audio/mp4',
        'audio/m4a', 'audio/x-m4a', 'audio/mp4a-latm',
        'audio/aac', 'audio/x-aac',
        'audio/flac', 'audio/x-flac',
        'video/mp4', 'video/webm', 'video/ogg', 'video/quicktime'
      ];

      const fileName = file.name.toLowerCase();
      const supportedExtensions = ['.wav', '.mp3', '.m4a', '.aac', '.flac', '.mp4', '.webm', '.ogg', '.mov'];
      const hasValidExtension = supportedExtensions.some(ext => fileName.endsWith(ext));
      const hasValidMimeType = supportedMimeTypes.includes(file.type);

      // Accept file if either MIME type OR extension is valid (some browsers don't set MIME types correctly)
      if (!hasValidMimeType && !hasValidExtension) {
        setError(`Unsupported file type for ${file.name}. Please select supported audio/video files (WAV, MP3, M4A, AAC, FLAC, MP4, WebM)`);
        addToast('error', 'Unsupported File', `${file.name} is not a supported audio file format`);
        announceToScreenReader(`Error: Unsupported file format selected for ${file.name}`);
        return;
      }

      // Validate file size (50MB limit)
      const maxSize = 50 * 1024 * 1024;
      if (file.size > maxSize) {
        setError(`File ${file.name} is too large. File size must be less than 50MB`);
        addToast('error', 'File Too Large', `${file.name} size must be less than 50MB`);
        announceToScreenReader(`Error: File ${file.name} is too large`);
        return;
      }

      addAudioFile(file);
      setError(null);
    });
  }, [announceToScreenReader, addAudioFile, addToast]);

