  // Download CSV template function for batch-csv mode
  const downloadCsvTemplate = useCallback(() => {
    // Define all CSV columns
    const headers = [
      'userId',
      'fileName',
      'age',
      'gender',
      'race',
      'ethnicity',
      'language',
      'weight',
      'zipcode',
      'sessionNotes'
    ];

