  const processMultipleFiles = useCallback(async () => {
    setIsProcessing(true);
    setError(null);

    // For batch processing modes, validate individual file metadata if needed
    if (processingMode === 'batch-files' || processingMode === 'batch-csv') {
      // Check that all files have userMetadata
      const filesWithoutMetadata = audioFiles.filter(file => !file.userMetadata);
      if (filesWithoutMetadata.length > 0) {
        setError('Some files are missing user metadata');
        addToast('error', 'Validation Error', 'All files must have user metadata in batch mode');
        setIsProcessing(false);
        return;
      }
    } else {
      // Original validation for shared metadata mode
      const validationErrors = validateMetadata();
      if (validationErrors.length > 0) {
        setError(`Validation error: ${validationErrors.join(', ')}`);
        addToast('error', 'Validation Error', validationErrors.join(', '));
        setIsProcessing(false);
        return;
      }
    }

    // Only process files that are in 'ready' state
    const filesToProcess = audioFiles.filter(file => fileStates[file.id] === 'ready');

    if (filesToProcess.length === 0) {
      addToast('info', 'No Files Ready', 'No files are ready to process');
      setIsProcessing(false);
      return;
    }

    const totalFiles = filesToProcess.length;
    let completedFiles = 0;

    // Initialize batch processing progress
    setBatchProcessingProgress({
      isProcessing: true,
      currentFile: 0,
      totalFiles,
      currentFileName: '',
      message: 'Starting batch file processing...'
    });

    try {
      for (const audioFile of filesToProcess) {
        completedFiles++;
        const fileName = audioFile.file.name;

        // Update progress
        setBatchProcessingProgress(prev => ({
          ...prev,
          currentFile: completedFiles,
          currentFileName: fileName,
          message: `Processing file ${completedFiles} of ${totalFiles}: ${fileName}`
        }));

        addToast('info', 'Processing File', `Processing ${fileName} (${completedFiles}/${totalFiles})`);

        // Set file state to processing
        setFileStates(prev => ({ ...prev, [audioFile.id]: 'processing' }));

        try {
          await processSingleFileById(audioFile.id, audioFile, {
            transcribeAudio: transcribeAudio && isTranscriptionEnabled
          });
          setFileStates(prev => ({ ...prev, [audioFile.id]: 'complete' }));
          addToast('success', 'File Complete', `${fileName} processed successfully`);

          // Small delay to allow UI updates and make progress visible
          await new Promise(resolve => setTimeout(resolve, 100));
        } catch (error) {
          // Extract detailed error information
          let errorCode = 'FILE_PROCESSING_ERROR';
          let errorMessage = 'An unexpected error occurred';
          let errorDetails: Record<string, unknown> = {};

          if (error && typeof error === 'object') {
            if ('code' in error && typeof error.code === 'string') {
              errorCode = error.code;
            }
            if ('message' in error && typeof error.message === 'string') {
              errorMessage = error.message;
            }
            if ('details' in error && typeof error.details === 'object') {
              errorDetails = error.details as Record<string, unknown>;
            }
          } else if (error instanceof Error) {
            errorMessage = error.message;
            errorCode = error.name || 'ERROR';
          }

          addToast('error', 'File Failed', `Failed to process ${audioFile.file.name}: ${errorMessage}`);

          // Set error state for this file with detailed error information
          setFileStates(prev => ({ ...prev, [audioFile.id]: 'error' }));
          setProcessingProgress(prev => ({
            ...prev,
            [audioFile.id]: {
              stage: 'error',
              progress: 0,
              message: `Failed: ${errorMessage}`,
              error: {
                code: errorCode,
                message: errorMessage,
                details: errorDetails
              }
            }
          }));
        }
      }

      addToast('success', 'Batch Complete', `Processed ${completedFiles} file${completedFiles !== 1 ? 's' : ''}`);
      announceToScreenReader(`Batch processing complete. ${completedFiles} files processed.`);

      // Update progress with completion message
      setBatchProcessingProgress(prev => ({
        ...prev,
        message: `Successfully processed ${completedFiles} files`
      }));

    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'An unexpected error occurred';
      setError(errorMessage);
      addToast('error', 'Batch Failed', errorMessage);
      announceToScreenReader(`Error: ${errorMessage}`);
    } finally {
      setIsProcessing(false);

      // Reset batch processing progress after a short delay to show completion
      setTimeout(() => {
        setBatchProcessingProgress({
          isProcessing: false,
          currentFile: 0,
          totalFiles: 0,
          currentFileName: '',
          message: ''
        });
      }, 2000);
    }
  }, [audioFiles, fileStates, validateMetadata, addToast, announceToScreenReader, processSingleFileById, transcribeAudio, isTranscriptionEnabled, selectedGroupId]);

  const startSingleFile = useCallback(async (fileId: string) => {
    const audioFile = audioFiles.find(f => f.id === fileId);
    if (!audioFile) return;

    // Validate metadata
    const validationErrors = validateMetadata();
    if (validationErrors.length > 0) {
      setError(`Validation error: ${validationErrors.join(', ')}`);
      addToast('error', 'Validation Error', validationErrors.join(', '));
      return;
    }

    setFileStates(prev => ({ ...prev, [fileId]: 'processing' }));

    try {
      await processSingleFileById(fileId, audioFile, {
        transcribeAudio: transcribeAudio && isTranscriptionEnabled
      });
      setFileStates(prev => ({ ...prev, [fileId]: 'complete' }));
      addToast('success', 'File Complete', `${audioFile.file.name} processed successfully`);
    } catch (error) {
      log.error(`Error processing ${audioFile.file.name}`, error);
      const errorMessage = error instanceof Error ? error.message : 'An unexpected error occurred';

      addToast('error', 'File Failed', `Failed to process ${audioFile.file.name}: ${errorMessage}`);
      setFileStates(prev => ({ ...prev, [fileId]: 'error' }));
      setProcessingProgress(prev => ({
        ...prev,
        [fileId]: { stage: 'error', progress: 0, message: `Failed: ${errorMessage}` }
      }));
    }
  }, [audioFiles, validateMetadata, addToast, processSingleFileById, transcribeAudio, isTranscriptionEnabled]);

  const processSingleFile = useCallback(async () => {
    if (!audioFile || !userMetadata.userId.trim()) {
      setError('Please select an audio file. User ID is automatically generated.');
      addToast('error', 'Missing Information', 'Please select an audio file. User ID is automatically generated.');
      return;
    }

    // Validate metadata
    const validationErrors = validateMetadata();
    if (validationErrors.length > 0) {
      setError(`Validation error: ${validationErrors.join(', ')}`);
      addToast('error', 'Validation Error', validationErrors.join(', '));
      return;
    }

    try {
      setError(null);

      // â”€â”€ DAM (local model) path â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
      // DAM is the only analysis mode. We generate a local session ID
      // and POST to the SK orchestration endpoint.
      {
        const localSessionId = crypto.randomUUID();
        const sessionData: SessionInfo = {
          sessionId: localSessionId,
          userId: userMetadata.userId.trim()
        };

        setProgress({ stage: 'initiating', progress: 10, message: 'Starting DAM analysis...' });
        announceToScreenReader('Starting DAM analysis');

        setProgress({ stage: 'analyzing', progress: 30, message: 'Uploading to local DAM model for analysis...' });
        announceToScreenReader('Submitting audio to local DAM model');

        const damPipelineResult = await submitToDam(
          audioFile.file,
          userMetadata.userId.trim(),
          sessionData.sessionId,
        );

        if (!damPipelineResult.success) {
          throw new Error(damPipelineResult.error || damPipelineResult.message || 'DAM pipeline failed');
        }

        setProgress({ stage: 'analyzing', progress: 75, message: 'DAM analysis complete, uploading audio...' });
        announceToScreenReader('DAM analysis complete, uploading audio file');

        const damPrediction = mapDamResultToPrediction(damPipelineResult);

        // Build user metadata for session storage
        const builtMetadata = buildMetadataFromUserData(userMetadata);

        // Upload audio file to blob storage for session details / playback
        let audioUrl: string | undefined;
        let audioFileName: string | undefined;
        try {
          const blobFileName = `${userMetadata.userId.trim()}_${sessionData.sessionId}_${Date.now()}.wav`;
          audioUrl = await uploadToAzureBlob(
            audioFile.file,
            blobFileName,
            undefined,
            getAuthenticatedUserId()
          );
          audioFileName = blobFileName;
        } catch (uploadError) {
          log.warn('DAM: Failed to upload audio to blob storage (session details will not show audio info)', { error: uploadError });
        }

        setProgress({ stage: 'analyzing', progress: 80, message: 'Saving results...' });

        // Save initial session data so SaveTranscription can find the session
        const initialSessionData = {
          sessionId: sessionData.sessionId,
          userId: getAuthenticatedUserId(),
          metadata_user_id: userMetadata.userId.trim(),
          groupId: selectedGroupId,
          ...(builtMetadata && { userMetadata: builtMetadata }),
          audioUrl: audioUrl,
          audioFileName: audioFileName || audioFile.file.name,
          status: 'processing',
          createdAt: new Date().toISOString(),
          updatedAt: new Date().toISOString(),
        };

        try {
          await apiService.saveSessionData(initialSessionData);
        } catch (saveError) {
          log.warn('Failed to save initial session data', { error: saveError });
        }

        // Transcribe audio if the checkbox is checked
        let transcriptionText: string | null = null;
        const effectiveTranscribeAudio = transcribeAudio && isTranscriptionEnabled;
        if (effectiveTranscribeAudio) {
          setProgress({ stage: 'analyzing', progress: 85, message: 'Transcribing audio...' });
          announceToScreenReader('Transcribing audio');
          try {
            const audioBlob: Blob = audioFile.file;
            const transcriptionResult: TranscriptionResult = await transcriptionService.transcribeAudio(audioBlob);
            if (!transcriptionResult.error && transcriptionResult.text) {
              transcriptionText = transcriptionResult.text;
              await apiService.saveTranscription(sessionData.sessionId, transcriptionText);
              addToast('success', 'Transcription Complete',
                `Audio transcription completed with ${Math.round(transcriptionResult.confidence * 100)}% confidence.`);
            }
          } catch (transcriptionError) {
            log.error('DAM transcription failed', transcriptionError);
            addToast('warning', 'Transcription Failed',
              `Audio transcription could not be completed: ${transcriptionError instanceof Error ? transcriptionError.message : 'Unknown error'}. DAM analysis results are still available.`);
          }
        }

        const analysisResult: AnalysisResult = {
          sessionId: sessionData.sessionId,
          depressionScore: safeParseFloat(damPrediction.predictedScoreDepression, 0),
          riskLevel: (() => {
            const score = safeParseFloat(damPrediction.predictedScoreDepression, 0);
            return score > 0.7 ? 'high' : score > 0.4 ? 'medium' : 'low';
          })(),
          confidence: undefined,
          insights: [
            'Analysis completed using local DAM model',
            damPrediction.predictedScoreDepression ? `Depression score: ${damPrediction.predictedScoreDepression}` : '',
            damPrediction.predictedScoreAnxiety ? `Anxiety score: ${damPrediction.predictedScoreAnxiety}` : '',
            damPipelineResult.totalElapsedMs ? `Pipeline completed in ${Math.round(damPipelineResult.totalElapsedMs)}ms` : '',
            'Results should be reviewed by a qualified healthcare professional',
          ].filter(i => i.trim() !== ''),
          timestamp: damPrediction.updatedAt || new Date().toISOString(),
          rawApiResponse: damPrediction,
          transcriptionText: transcriptionText || undefined,
        };

        const finalSessionData = {
          ...initialSessionData,
          provider: 'local-dam',
          audioUrl: audioUrl,
          audioFileName: audioFileName || audioFile.file.name,
          prediction: damPrediction,
          transcription: transcriptionText || undefined,
          analysisResults: {
            depressionScore: safeParseFloat(damPrediction.predictedScoreDepression),
            anxietyScore: safeParseFloat(damPrediction.predictedScoreAnxiety),
            riskLevel: analysisResult.riskLevel || 'unknown',
            confidence: undefined,
            insights: analysisResult.insights || [],
            transcriptionText: transcriptionText || undefined,
            completedAt: new Date().toISOString(),
          },
          status: 'completed',
          completedAt: new Date().toISOString(),
          updatedAt: new Date().toISOString(),
        };

        try {
          await apiService.saveSessionData(finalSessionData);
          addToast('success', 'Session Saved', 'DAM analysis results saved to session storage.');
        } catch (saveErr) {
          log.error('Failed to save DAM analysis results', saveErr);
          addToast('warning', 'Save Warning', 'DAM analysis completed but failed to save to session storage.');
        }

        setProgress({ stage: 'complete', progress: 100, message: 'DAM analysis complete!' });
        setResult(analysisResult);
        addToast('success', 'Analysis Complete', 'Local DAM model analysis has been completed successfully.');
        announceToScreenReader('Local DAM model analysis completed successfully');
      }
    } catch (err) {
      log.error('Processing error', err);
      const errorMessage = err instanceof Error ? err.message : 'An unexpected error occurred';
      setError(errorMessage);
      setProgress({ stage: 'error', progress: 0, message: 'Processing failed' });
      addToast('error', 'Processing Failed', errorMessage);
      announceToScreenReader(`Error: ${errorMessage}`);
    }
  }, [audioFile, userMetadata.userId, announceToScreenReader, validateMetadata, buildMetadata, safeParseFloat, transcribeAudio, selectedGroupId]);

  const getProgressColor = useCallback((stage: string) => {
    switch (stage) {
      case 'error': return 'processing-progress__fill--error';
      case 'complete': return 'processing-progress__fill--success';
      default: return ''; // Use default blue color from CSS
    }
  }, []);

  return (
    <div className="max-w-4xl mx-auto p-6 space-y-8">
