          {/* Mode Switcher */}
          <div className="flex items-center space-x-4">
            <div className="flex items-center space-x-3">
              <span className="text-sm font-medium text-gray-700 dark:text-gray-300">Processing Mode:</span>
              <div className="flex items-center space-x-2">
                {['single', 'batch-files', 'batch-csv'].map((mode) => (
                  <button
                    key={mode}
                    type="button"
                    onClick={() => {
                      setProcessingMode(mode as ProcessingMode);
                      setStoredProcessingMode(mode); // Save the actual mode string

                      // Completely reset all state when switching modes
                      resetState();

                      // Announce the mode change to screen readers
                      announceToScreenReader(`Switched to ${mode === 'single' ? 'Single File' : mode === 'batch-files' ? 'Batch Files' : 'CSV Batch'} mode`);
                    }}
                    className={`px-3 py-1 text-xs font-medium rounded-full transition-colors focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2 dark:focus:ring-offset-gray-800 ${
                      processingMode === mode
                        ? 'bg-blue-600 text-white hover:bg-blue-700'
                        : 'bg-gray-200 text-gray-700 hover:bg-gray-300 dark:bg-gray-700 dark:text-gray-300 dark:hover:bg-gray-600'
                    }`}
                  >
                    {mode === 'single' && 'Single File'}
                    {mode === 'batch-files' && 'Batch Files'}
                    {mode === 'batch-csv' && 'CSV Batch'}
                  </button>
                ))}
              </div>
            </div>

            {/* Status Badge */}
            <div className={`inline-flex items-center px-3 py-1 rounded-full text-xs font-medium ${
              processingMode === 'single'
                ? 'bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-200'
                : processingMode === 'batch-files'
                ? 'bg-blue-100 text-blue-800 dark:bg-blue-900 dark:text-blue-200'
                : 'bg-purple-100 text-purple-800 dark:bg-purple-900 dark:text-purple-200'
            }`}>
              {processingMode === 'single' ? (
                <>
                  <svg className="w-3 h-3 mr-1" fill="currentColor" viewBox="0 0 20 20">
                    <path fillRule="evenodd" d="M4 4a2 2 0 00-2 2v8a2 2 0 002 2h12a2 2 0 002-2V6a2 2 0 00-2-2H4zm12 2H4v8h12V6z" clipRule="evenodd" />
                  </svg>
                  Single File Processing
                </>
              ) : processingMode === 'batch-files' ? (
                <>
                  <svg className="w-3 h-3 mr-1" fill="currentColor" viewBox="0 0 20 20">
                    <path fillRule="evenodd" d="M3 4a1 1 0 011-1h12a1 1 0 110 2H4a1 1 0 01-1-1zm0 4a1 1 0 011-1h12a1 1 0 110 2H4a1 1 0 01-1-1zm0 4a1 1 0 011-1h12a1 1 0 110 2H4a1 1 0 01-1-1z" clipRule="evenodd" />
                  </svg>
                  Batch File Processing
                </>
              ) : (
                <>
                  <svg className="w-3 h-3 mr-1" fill="currentColor" viewBox="0 0 20 20">
                    <path fillRule="evenodd" d="M3 17a1 1 0 011-1h12a1 1 0 110 2H4a1 1 0 01-1-1zm3.293-7.707a1 1 0 011.414 0L9 10.586V3a1 1 0 112 0v7.586l1.293-1.293a1 1 0 111.414 1.414l-3 3a1 1 0 01-1.414 0l-3-3a1 1 0 010-1.414z" clipRule="evenodd" />
                  </svg>
                  CSV Batch Processing
                </>
              )}
            </div>
          </div>
        </div>

        <h1 className="text-3xl font-bold text-gray-900 dark:text-white mb-2">
          Upload & Analyze Audio
        </h1>
        <p className="text-gray-600 dark:text-gray-300 mb-4">
          Upload {processingMode === 'single' ? 'an audio file' : processingMode === 'batch-files' ? 'multiple audio files' : 'a folder of audio files with CSV metadata'} for behavioral health analysis using AI-powered speech pattern recognition
        </p>

        {/* Mode Description */}
        <div className={`inline-flex items-center px-4 py-2 rounded-lg text-sm ${
          processingMode === 'single'
            ? 'bg-green-50 text-green-700 dark:bg-green-900/20 dark:text-green-300'
            : processingMode === 'batch-files'
            ? 'bg-blue-50 text-blue-700 dark:bg-blue-900/20 dark:text-blue-300'
            : 'bg-purple-50 text-purple-700 dark:bg-purple-900/20 dark:text-purple-300'
        }`}>
          {processingMode === 'single' ? (
            <>
              <svg className="w-4 h-4 mr-2" fill="currentColor" viewBox="0 0 20 20">
                <path fillRule="evenodd" d="M3 17a1 1 0 011-1h12a1 1 0 110 2H4a1 1 0 01-1-1zm3.293-7.707a1 1 0 011.414 0L9 10.586V3a1 1 0 112 0v7.586l1.293-1.293a1 1 0 111.414 1.414l-3 3a1 1 0 01-1.414 0l-3-3a1 1 0 010-1.414z" clipRule="evenodd" />
              </svg>
              Upload and analyze one file at a time with detailed progress tracking
            </>
          ) : processingMode === 'batch-files' ? (
            <>
              <svg className="w-4 h-4 mr-2" fill="currentColor" viewBox="0 0 20 20">
                <path d="M9 12a1 1 0 000 2h2a1 1 0 100-2H9z" />
                <path fillRule="evenodd" d="M4 4a2 2 0 012-2h8a2 2 0 012 2v12a2 2 0 01-2 2H6a2 2 0 01-2-2V4zm2 0v12h8V4H6z" clipRule="evenodd" />
              </svg>
              Process multiple files with individual patient metadata for each file
            </>
          ) : (
            <>
              <svg className="w-4 h-4 mr-2" fill="currentColor" viewBox="0 0 20 20">
                <path fillRule="evenodd" d="M3 17a1 1 0 011-1h12a1 1 0 110 2H4a1 1 0 01-1-1zm3.293-7.707a1 1 0 011.414 0L9 10.586V3a1 1 0 112 0v7.586l1.293-1.293a1 1 0 111.414 1.414l-3 3a1 1 0 01-1.414 0l-3-3a1 1 0 010-1.414z" clipRule="evenodd" />
              </svg>
              Select a folder and CSV file for automated batch processing
            </>
          )}
        </div>
      </div>

      {/* Processing Options */}
      <div className="bg-white dark:bg-gray-800 rounded-lg shadow-md">
        <button
          type="button"
          className="w-full p-6 cursor-pointer hover:bg-gray-50 dark:hover:bg-gray-700/50 transition-colors text-left"
          onClick={() => toggleSectionCollapse('processingOptions')}
          aria-expanded={!collapsedSections.processingOptions}
          aria-controls="processing-options-content"
        >
          <div className="flex items-center justify-between">
            <h2 className="text-xl font-semibold text-gray-900 dark:text-white">
              Processing Options
            </h2>
            <svg
              className={`w-5 h-5 text-gray-500 transition-transform duration-200 ${
                collapsedSections.processingOptions ? 'rotate-180' : ''
              }`}
              fill="none"
              stroke="currentColor"
              viewBox="0 0 24 24"
            >
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
            </svg>
          </div>
        </button>

        {!collapsedSections.processingOptions && (
          <div id="processing-options-content" className="px-6 pb-6">
            <p className="text-gray-600 dark:text-gray-400 mb-4">
              Choose which analysis options to run on your audio files.
            </p>

        <div className="space-y-4">
          {/* DAM Analysis (always enabled - only analysis method) */}
          <div className="flex items-start">
            <div className="mt-1 h-4 w-4 flex items-center justify-center text-green-600">
              <svg className="h-4 w-4" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd" /></svg>
            </div>
            <div className="ml-3">
              <span className="text-sm font-medium text-gray-900 dark:text-white">
                DAM Analysis
              </span>
              <p className="text-sm text-gray-600 dark:text-gray-400">
                Analyze audio using the DAM (Depression &amp; Anxiety Model) for behavioral health assessment. Audio conversion and prediction are handled server-side.
              </p>
            </div>
          </div>

          <div className="flex items-start">
            <input
              id="transcribeAudio"
              type="checkbox"
              checked={transcribeAudio && isTranscriptionEnabled}
              disabled={!isTranscriptionEnabled}
              onChange={(e) => {
                log.debug('Transcribe Audio checkbox changed', { checked: e.target.checked });
                setTranscribeAudio(e.target.checked);
              }}
              className={`mt-1 h-4 w-4 text-blue-600 focus:ring-blue-500 border-gray-300 dark:border-gray-600 rounded dark:bg-gray-700 ${
                !isTranscriptionEnabled ? 'opacity-50 cursor-not-allowed' : ''
              }`}
            />
            <div className="ml-3">
              <label htmlFor="transcribeAudio" className={`text-sm font-medium ${
                !isTranscriptionEnabled
                  ? 'text-gray-400 dark:text-gray-500'
                  : 'text-gray-900 dark:text-white'
              }`}>
                Transcribe Audio
                {!isTranscriptionEnabled && (
                  <span className="ml-2 text-xs text-red-500 dark:text-red-400">
                    (Disabled)
                  </span>
                )}
              </label>
              <p className={`text-sm ${
                !isTranscriptionEnabled
                  ? 'text-gray-400 dark:text-gray-500'
                  : 'text-gray-600 dark:text-gray-400'
              }`}>
                {!isTranscriptionEnabled
                  ? 'Transcription service is disabled in configuration'
                  : 'Convert audio to text using speech recognition technology'
                }
              </p>
            </div>
          </div>
        </div>
          </div>
        )}
      </div>

      {/* Group Selection */}
      <div className="bg-white dark:bg-gray-800 rounded-lg shadow-md">
        <div className="p-6">
          <h2 className="text-xl font-semibold text-gray-900 dark:text-white mb-4">
            Group Assignment (Optional)
          </h2>
          <p className="text-gray-600 dark:text-gray-400 mb-4">
            Organize your processed files by assigning them to a group. Groups help you track and analyze related sessions together.
          </p>

          <GroupSelector
            selectedGroupId={selectedGroupId}
            onGroupChange={setSelectedGroupId}
            onCreateGroup={async (groupName, description) => {
              const userId = user?.id || getUserId();
              const response = await fileGroupService.createFileGroup({
                groupName,
                description,
                createdBy: userId
              }, userId);

              if (response.success && response.fileGroup) {
                addToast('success', 'Group Created', `Group "${groupName}" has been created successfully.`);
                return response.fileGroup.groupId;
              } else {
                addToast('error', 'Group Creation Failed', response.message || 'Failed to create group');
                throw new Error(response.message || 'Failed to create group');
              }
            }}
            onDeleteGroup={async (groupId, groupName) => {
              const response = await fileGroupService.deleteFileGroup(groupId);

              if (response.success) {
                addToast('success', 'Group Deleted', `Group "${groupName}" and all associated sessions have been deleted successfully.`);
              } else {
                addToast('error', 'Delete Failed', response.message || 'Failed to delete group');
                throw new Error(response.message || 'Failed to delete group');
              }
            }}
            showDeleteButton={true}
            className="mt-4"
          />
        </div>
      </div>

      {/* Folder Selection for CSV Batch Mode - Must come before Patient Info */}
      {processingMode === 'batch-csv' && (
        <div className="bg-white dark:bg-gray-800 rounded-lg shadow-md p-6">
          <h2 className="text-xl font-semibold text-gray-900 dark:text-white mb-4 flex items-center">
            <span className="inline-flex items-center justify-center w-7 h-7 rounded-full bg-blue-100 dark:bg-blue-900 text-blue-600 dark:text-blue-400 text-sm font-bold mr-3">1</span>
            Select Folder Containing Audio Files
          </h2>
          <p className="text-gray-600 dark:text-gray-400 mb-4">
            Select the folder that contains your audio files. The filenames will be used to generate the CSV template.
          </p>
          <div className="flex items-center gap-4">
            <button
              type="button"
              onClick={() => folderInputRef.current?.click()}
              className="inline-flex items-center px-4 py-2 border border-transparent text-sm font-medium rounded-md text-white bg-blue-600 hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500 dark:focus:ring-offset-gray-800"
            >
              <Upload className="h-4 w-4 mr-2" />
              Select Folder
            </button>
            <input
              ref={folderInputRef}
              type="file"
              className="hidden"
              onChange={handleFolderSelect}
              {...{ webkitdirectory: '', directory: '' } as any}
              aria-label="Select folder containing audio files"
            />
            {csvFolderFiles.length > 0 ? (
              <div className="flex items-center text-sm text-green-600 dark:text-green-400">
                <CheckCircle className="h-4 w-4 mr-1" />
                {csvFolderFiles.length} audio file(s) found
              </div>
            ) : (
              <span className="text-sm text-gray-500 dark:text-gray-400">
                No folder selected
              </span>
            )}
          </div>
          {csvFolderFiles.length > 0 && (
