    if (!timestamp) return 'Not available';

    try {
      const date = new Date(timestamp);
      if (isNaN(date.getTime())) {
        return 'Not available';
      }

      return date.toLocaleString(undefined, {
        year: 'numeric',
        month: 'short',
        day: 'numeric',
        hour: '2-digit',
        minute: '2-digit',
        second: '2-digit'
      });
