/**
 * Chat Transcript Service for continuously saving conversation transcripts to blob storage
 * Handles session management and real-time conversation updates
 */

import { env } from '@/utils/env';
import { Logger } from '@/utils/logger';

const log = Logger.create('ChatTranscriptService');

export interface ChatMessage {
  id: string;
  role: 'user' | 'assistant' | 'system';
  content: string;
  timestamp: string;
  messageType?: string; // Optional: "phq-assessment", "general-chat", etc.
  additionalData?: Record<string, any>;
  // PHQ Assessment metadata
  isPhqQuestion?: boolean;
  isPhqAnswer?: boolean;
  phqType?: 2 | 9;
  phqQuestionNumber?: number; // 1-9
  phqAnswerValue?: number; // 0-3 (the actual answer score)
  assessmentId?: string; // Unique ID for the PHQ assessment session
}

export interface ChatTranscript {
  userId: string;
  sessionId: string;
  createdAt: string;
  lastUpdated: string;
  sessionEndedAt?: string;
  isActive: boolean;
  messages: ChatMessage[];
  metadata?: {
    userAgent?: string;
    clientTimezone?: string;
    ipAddress?: string;
    platform?: string;
    customData?: Record<string, any>;
  };
}

export interface ChatTranscriptSaveRequest {
  transcriptData: ChatTranscript;
  metadata?: Record<string, any>;
  containerName?: string;
  fileName?: string;
}

class ChatTranscriptService {
  private currentTranscript: ChatTranscript | null = null;
  private saveQueue: ChatMessage[] = [];
  private isSaving = false;
  private saveTimer: NodeJS.Timeout | null = null;
  private readonly saveDelay = 1000; // 1 second delay to batch rapid messages

  /**
   * Initialize a new chat session
   */
  initializeSession(userId: string, sessionId?: string): ChatTranscript {
    const newSessionId = sessionId || this.generateSessionId();

    this.currentTranscript = {
      userId,
      sessionId: newSessionId,
      createdAt: new Date().toISOString(),
      lastUpdated: new Date().toISOString(),
      isActive: true,
      messages: [],
      metadata: {
        userAgent: navigator.userAgent,
        clientTimezone: Intl.DateTimeFormat().resolvedOptions().timeZone,
        platform: navigator.platform,
        customData: {}
      }
    };

    // Save initial empty transcript
    this.saveTranscriptImmediate();

    return this.currentTranscript;
  }

  /**
   * Add a message to the current transcript
   */
  addMessage(message: Omit<ChatMessage, 'id' | 'timestamp'>): void {
    if (!this.currentTranscript) {
      log.warn('No active chat session. Initialize session first.');
      return;
    }

    const fullMessage: ChatMessage = {
      ...message,
      id: this.generateMessageId(),
      timestamp: new Date().toISOString()
    };

    this.currentTranscript.messages.push(fullMessage);
    this.currentTranscript.lastUpdated = new Date().toISOString();

    // Add to save queue and schedule save
    this.saveQueue.push(fullMessage);
    this.scheduleDelayedSave();
  }

  /**
   * Add a user message
   */
  addUserMessage(content: string, messageType?: string, additionalData?: Record<string, any>): void {
    this.addMessage({
      role: 'user',
      content,
      messageType,
      additionalData
    });
  }

  /**
   * Add an assistant message
   */
  addAssistantMessage(content: string, messageType?: string, additionalData?: Record<string, any>): void {
    this.addMessage({
      role: 'assistant',
      content,
      messageType,
      additionalData
    });
  }

  /**
   * Add a system message
   */
  addSystemMessage(content: string, messageType?: string, additionalData?: Record<string, any>): void {
    this.addMessage({
      role: 'system',
      content,
      messageType,
      additionalData
    });
  }

  /**
   * End the current session
   */
  endSession(): void {
    if (!this.currentTranscript) return;

    this.currentTranscript.isActive = false;
    this.currentTranscript.sessionEndedAt = new Date().toISOString();
    this.currentTranscript.lastUpdated = new Date().toISOString();

    // Force immediate save for session end
    this.saveTranscriptImmediate();
  }

  /**
   * Get the current transcript
   */
  getCurrentTranscript(): ChatTranscript | null {
    return this.currentTranscript;
  }

  /**
   * Get session summary
   */
  getSessionSummary(): { messageCount: number; duration: string; isActive: boolean } | null {
    if (!this.currentTranscript) return null;

    const messageCount = this.currentTranscript.messages.length;
    const startTime = new Date(this.currentTranscript.createdAt);
    const endTime = this.currentTranscript.sessionEndedAt ?
      new Date(this.currentTranscript.sessionEndedAt) :
      new Date();

    const durationMs = endTime.getTime() - startTime.getTime();
    const durationMinutes = Math.floor(durationMs / 60000);
    const durationSeconds = Math.floor((durationMs % 60000) / 1000);
    const duration = `${durationMinutes}m ${durationSeconds}s`;

    return {
      messageCount,
      duration,
      isActive: this.currentTranscript.isActive
    };
  }

  /**
   * Schedule a delayed save to batch rapid messages
   */
  private scheduleDelayedSave(): void {
    if (this.saveTimer) {
      clearTimeout(this.saveTimer);
    }

    this.saveTimer = setTimeout(() => {
      this.saveTranscriptImmediate();
    }, this.saveDelay);
  }

  /**
   * Save transcript immediately
   */
  private async saveTranscriptImmediate(): Promise<void> {
    if (!this.currentTranscript || this.isSaving) return;

    try {
      this.isSaving = true;

      // Clear the save queue since we're saving now
      this.saveQueue = [];

      // Clear any pending timer
      if (this.saveTimer) {
        clearTimeout(this.saveTimer);
        this.saveTimer = null;
      }

      const apiBaseUrl = env.API_BASE_URL;
      const endpoint = `${apiBaseUrl}/SaveChatTranscript`;

      const request: ChatTranscriptSaveRequest = {
        transcriptData: { ...this.currentTranscript },
        metadata: {
          saveTimestamp: new Date().toISOString(),
          messageCount: this.currentTranscript.messages.length,
          sessionActive: this.currentTranscript.isActive
        },
        containerName: 'chat-transcripts'
      };

      const response = await fetch(endpoint, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify(request)
      });

      if (!response.ok) {
        const errorText = await response.text();
        throw new Error(`Failed to save chat transcript: ${response.status} - ${errorText}`);
      }

      const result = await response.json();
      log.info('Chat transcript saved successfully', { result });

    } catch (error) {
      log.error('Error saving chat transcript', error);

      // Retry failed saves after a delay
      setTimeout(() => {
        if (this.currentTranscript && this.saveQueue.length === 0) {
          this.saveTranscriptImmediate();
        }
      }, 5000); // Retry after 5 seconds
    } finally {
      this.isSaving = false;
    }
  }

  /**
   * Force save without delay (for critical events)
   */
  async forceSave(): Promise<void> {
    if (this.saveTimer) {
      clearTimeout(this.saveTimer);
      this.saveTimer = null;
    }
    await this.saveTranscriptImmediate();
  }

  /**
   * Update custom metadata
   */
  updateMetadata(customData: Record<string, any>): void {
    if (!this.currentTranscript) return;

    if (!this.currentTranscript.metadata) {
      this.currentTranscript.metadata = {};
    }

    if (!this.currentTranscript.metadata.customData) {
      this.currentTranscript.metadata.customData = {};
    }

    Object.assign(this.currentTranscript.metadata.customData, customData);
    this.currentTranscript.lastUpdated = new Date().toISOString();

    // Schedule save for metadata updates
    this.scheduleDelayedSave();
  }

  /**
   * Generate unique session ID
   */
  private generateSessionId(): string {
    return `session-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
  }

  /**
   * Generate unique message ID
   */
  private generateMessageId(): string {
    return `msg-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
  }

  /**
   * Cleanup resources
   */
  cleanup(): void {
    if (this.saveTimer) {
      clearTimeout(this.saveTimer);
      this.saveTimer = null;
    }

    // Force final save if there are pending messages
    if (this.currentTranscript && this.saveQueue.length > 0) {
      this.saveTranscriptImmediate();
    }
  }
}

// Export singleton instance
export const chatTranscriptService = new ChatTranscriptService();
export default chatTranscriptService;

/**
 * PHQ Assessment Progress Service for continuously saving assessment progress to blob storage
 * Tracks question-by-question progress during PHQ-2 and PHQ-9 assessments
 */

import { env } from '@/utils/env';
import { Logger } from '@/utils/logger';

const log = Logger.create('PhqProgress');

export interface PhqAnsweredQuestion {
  questionNumber: number;
  questionText: string;
  answer: number;
  answeredAt: string;
  attempts: number;
  wasSkipped: boolean;
}

export interface PhqAssessmentProgress {
  userId: string;
  assessmentId: string;
  assessmentType: 'PHQ-2' | 'PHQ-9';
  startedAt: string;
  lastUpdated: string;
  completedAt?: string;
  isCompleted: boolean;
  totalQuestions: number;
  answeredQuestions: PhqAnsweredQuestion[];
  totalScore?: number;
  severity?: string;
  interpretation?: string;
  recommendations?: string[];
  metadata?: {
    sessionId?: string;
    userAgent?: string;
    clientTimezone?: string;
    ipAddress?: string;
    customData?: Record<string, any>;
  };
}

export interface PhqProgressSaveRequest {
  progressData: PhqAssessmentProgress;
  metadata?: Record<string, any>;
  containerName?: string;
  fileName?: string;
}

class PhqProgressService {
  private currentProgress: PhqAssessmentProgress | null = null;
  private isSaving = false;
  private saveTimer: NodeJS.Timeout | null = null;
  private readonly saveDelay = 500; // 500ms delay for progress updates

  /**
   * Start a new PHQ assessment progress tracking
   */
  startAssessment(userId: string, assessmentType: 'PHQ-2' | 'PHQ-9', assessmentId?: string): PhqAssessmentProgress {
    const newAssessmentId = assessmentId || this.generateAssessmentId();
    const totalQuestions = assessmentType === 'PHQ-2' ? 2 : 9;

    this.currentProgress = {
      userId,
      assessmentId: newAssessmentId,
      assessmentType,
      startedAt: new Date().toISOString(),
      lastUpdated: new Date().toISOString(),
      isCompleted: false,
      totalQuestions,
      answeredQuestions: [],
      metadata: {
        sessionId: this.getSessionId(),
        userAgent: navigator.userAgent,
        clientTimezone: Intl.DateTimeFormat().resolvedOptions().timeZone,
        customData: {}
      }
    };

    // Save initial empty progress
    this.saveProgressImmediate();

    return this.currentProgress;
  }

  /**
   * Record an answer to a question
   */
  recordAnswer(
    questionNumber: number,
    questionText: string,
    answer: number,
    attempts: number = 1,
    wasSkipped: boolean = false
  ): boolean {
    if (!this.currentProgress) {
      log.warn('No active PHQ assessment. Start assessment first.');
      return false;
    }

    if (answer < 0 || answer > 3) {
      log.warn('Invalid answer value. Must be between 0 and 3.');
      return false;
    }

    // Remove existing answer for this question if it exists
    this.currentProgress.answeredQuestions = this.currentProgress.answeredQuestions.filter(
      q => q.questionNumber !== questionNumber
    );

    // Add new answer
    const answeredQuestion: PhqAnsweredQuestion = {
      questionNumber,
      questionText,
      answer,
      answeredAt: new Date().toISOString(),
      attempts,
      wasSkipped
    };

    this.currentProgress.answeredQuestions.push(answeredQuestion);
    this.currentProgress.lastUpdated = new Date().toISOString();

    // Sort by question number
    this.currentProgress.answeredQuestions.sort((a, b) => a.questionNumber - b.questionNumber);

    // Check if assessment is complete
    this.checkAndUpdateCompletion();

    // Schedule save
    this.scheduleDelayedSave();

    return true;
  }

  /**
   * Mark a question as skipped
   */
  skipQuestion(questionNumber: number, questionText: string, attempts: number = 3): void {
    if (!this.currentProgress) return;

    // Record as skipped (no answer)
    const skippedQuestion: PhqAnsweredQuestion = {
      questionNumber,
      questionText,
      answer: -1, // Use -1 to indicate skipped
      answeredAt: new Date().toISOString(),
      attempts,
      wasSkipped: true
    };

    // Remove existing entry for this question
    this.currentProgress.answeredQuestions = this.currentProgress.answeredQuestions.filter(
      q => q.questionNumber !== questionNumber
    );

    this.currentProgress.answeredQuestions.push(skippedQuestion);
    this.currentProgress.lastUpdated = new Date().toISOString();

    // Sort by question number
    this.currentProgress.answeredQuestions.sort((a, b) => a.questionNumber - b.questionNumber);

    // Schedule save
    this.scheduleDelayedSave();
  }

  /**
   * Complete the assessment with final scores and interpretation
   */
  completeAssessment(
    totalScore: number,
    severity: string,
    interpretation: string,
    recommendations: string[]
  ): void {
    if (!this.currentProgress) return;

    this.currentProgress.isCompleted = true;
    this.currentProgress.completedAt = new Date().toISOString();
    this.currentProgress.lastUpdated = new Date().toISOString();
    this.currentProgress.totalScore = totalScore;
    this.currentProgress.severity = severity;
    this.currentProgress.interpretation = interpretation;
    this.currentProgress.recommendations = recommendations;

    // Force immediate save for completion
    this.saveProgressImmediate();
  }

  /**
   * Get current assessment progress
   */
  getCurrentProgress(): PhqAssessmentProgress | null {
    return this.currentProgress;
  }

  /**
   * Get progress summary
   */
  getProgressSummary(): { answeredCount: number; totalQuestions: number; percentComplete: number; isCompleted: boolean } | null {
    if (!this.currentProgress) return null;

    const answeredCount = this.currentProgress.answeredQuestions.filter(q => q.answer >= 0).length;
    const totalQuestions = this.currentProgress.totalQuestions;
    const percentComplete = Math.round((answeredCount / totalQuestions) * 100);

    return {
      answeredCount,
      totalQuestions,
      percentComplete,
      isCompleted: this.currentProgress.isCompleted
    };
  }

  /**
   * Update custom metadata
   */
  updateMetadata(customData: Record<string, any>): void {
    if (!this.currentProgress) return;

    if (!this.currentProgress.metadata) {
      this.currentProgress.metadata = {};
    }

    if (!this.currentProgress.metadata.customData) {
      this.currentProgress.metadata.customData = {};
    }

    Object.assign(this.currentProgress.metadata.customData, customData);
    this.currentProgress.lastUpdated = new Date().toISOString();

    // Schedule save for metadata updates
    this.scheduleDelayedSave();
  }

  /**
   * Check if assessment is complete and update status
   */
  private checkAndUpdateCompletion(): void {
    if (!this.currentProgress) return;

    // Count valid answers (not skipped)
    const validAnswers = this.currentProgress.answeredQuestions.filter(q => q.answer >= 0).length;

    // Assessment is complete if all questions have valid answers
    if (validAnswers === this.currentProgress.totalQuestions && !this.currentProgress.isCompleted) {
      // Don't auto-complete here, wait for explicit completion call with scores
      // This just tracks question progress
    }
  }

  /**
   * Schedule a delayed save
   */
  private scheduleDelayedSave(): void {
    if (this.saveTimer) {
      clearTimeout(this.saveTimer);
    }

    this.saveTimer = setTimeout(() => {
      this.saveProgressImmediate();
    }, this.saveDelay);
  }

  /**
   * Save progress immediately
   */
  private async saveProgressImmediate(): Promise<void> {
    if (!this.currentProgress || this.isSaving) return;

    try {
      this.isSaving = true;

      // Clear any pending timer
      if (this.saveTimer) {
        clearTimeout(this.saveTimer);
        this.saveTimer = null;
      }

      const apiBaseUrl = env.API_BASE_URL;
      const endpoint = `${apiBaseUrl}/SavePhqProgress`;

      log.debug('Saving PHQ progress to', { endpoint });
      log.debug('Progress data', {
        assessmentId: this.currentProgress.assessmentId,
        userId: this.currentProgress.userId,
        assessmentType: this.currentProgress.assessmentType,
        isCompleted: this.currentProgress.isCompleted,
        questionsAnswered: this.currentProgress.answeredQuestions.length,
        totalQuestions: this.currentProgress.totalQuestions
      });

      const request: PhqProgressSaveRequest = {
        progressData: { ...this.currentProgress },
        metadata: {
          saveTimestamp: new Date().toISOString(),
          questionsAnswered: this.currentProgress.answeredQuestions.length,
          isCompleted: this.currentProgress.isCompleted
        },
        containerName: 'phq'
      };

      const response = await fetch(endpoint, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify(request)
      });

      if (!response.ok) {
        const errorText = await response.text();
        throw new Error(`Failed to save PHQ progress: ${response.status} - ${errorText}`);
      }

      const result = await response.json();
      log.info('PHQ assessment progress saved successfully', result);

    } catch (error) {
      log.error('Error saving PHQ assessment progress', error);

      // Retry failed saves after a delay
      setTimeout(() => {
        if (this.currentProgress) {
          this.saveProgressImmediate();
        }
      }, 5000); // Retry after 5 seconds
    } finally {
      this.isSaving = false;
    }
  }

  /**
   * Force save without delay (for critical events)
   */
  async forceSave(): Promise<void> {
    if (this.saveTimer) {
      clearTimeout(this.saveTimer);
      this.saveTimer = null;
    }
    await this.saveProgressImmediate();
  }

  /**
   * Reset progress (start new assessment)
   */
  resetProgress(): void {
    this.currentProgress = null;

    if (this.saveTimer) {
      clearTimeout(this.saveTimer);
      this.saveTimer = null;
    }
  }

  /**
   * Generate unique assessment ID
   */
  private generateAssessmentId(): string {
    return `phq-progress-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
  }

  /**
   * Get session ID from session storage or generate one
   */
  private getSessionId(): string {
    let sessionId = sessionStorage.getItem('chat-session-id');
    if (!sessionId) {
      sessionId = `session-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
      sessionStorage.setItem('chat-session-id', sessionId);
    }
    return sessionId;
  }

  /**
   * Cleanup resources
   */
  cleanup(): void {
    if (this.saveTimer) {
      clearTimeout(this.saveTimer);
      this.saveTimer = null;
    }

    // Force final save if there is current progress
    if (this.currentProgress) {
      this.saveProgressImmediate();
    }
  }
}

// Export singleton instance
export const phqProgressService = new PhqProgressService();
export default phqProgressService;

/**
 * PHQ Session Service for continuously saving PHQ assessment sessions to blob storage
 * Saves progressively as the assessment progresses, similar to chat transcript service
 */

import { Logger } from '@/utils/logger';

const log = Logger.create('PhqSession');

export interface PhqQuestionResponse {
  questionNumber: number;
  questionText: string;
  answer?: number; // 0-3
  attempts: number;
  skipped: boolean;
  answeredAt?: string;
}

export interface PhqSessionMessage {
  id: string;
  role: 'user' | 'assistant';
  content: string;
  timestamp: string;
  messageType: string;
  additionalData?: Record<string, any>;
}

export interface PhqSession {
  userId: string;
  sessionId: string; // Same as chat transcript session ID
  assessmentId: string; // Unique ID for this specific assessment
  assessmentType: 'PHQ-2' | 'PHQ-9';
  createdAt: string;
  lastUpdated: string;
  completedAt?: string;
  isCompleted: boolean;
  questions: PhqQuestionResponse[]; // Structured question/answer data
  messages: PhqSessionMessage[]; // Complete conversational flow during assessment
  totalScore?: number;
  severity?: string;
  metadata?: {
    conversationSessionId: string; // Links to chat transcript
    userAgent?: string;
    clientTimezone?: string;
    version?: string;
  };
}

export interface PhqSessionSaveRequest {
  sessionData: PhqSession;
  metadata?: Record<string, any>;
  containerName?: string;
  fileName?: string;
}

class PhqSessionService {
  private currentSession: PhqSession | null = null;
  private saveTimer: NodeJS.Timeout | null = null;
  private readonly saveDelay = 1000; // 1 second delay to batch rapid updates

  /**
   * Initialize a new PHQ assessment session
   */
  initializeSession(
    userId: string,
    sessionId: string,
    assessmentId: string,
    assessmentType: 'PHQ-2' | 'PHQ-9'
  ): PhqSession {
    const questionCount = assessmentType === 'PHQ-2' ? 2 : 9;

    this.currentSession = {
      userId,
      sessionId,
      assessmentId,
      assessmentType,
      createdAt: new Date().toISOString(),
      lastUpdated: new Date().toISOString(),
      isCompleted: false,
      questions: Array.from({ length: questionCount }, (_, i) => ({
        questionNumber: i + 1,
        questionText: '', // Will be filled when question is asked
        answer: undefined,
        attempts: 0,
        skipped: false
      })),
      messages: [], // Will be filled as conversation progresses
      metadata: {
        conversationSessionId: sessionId,
        userAgent: navigator.userAgent,
        clientTimezone: Intl.DateTimeFormat().resolvedOptions().timeZone,
        version: '1.0.0'
      }
    };

    log.info('PHQ Session initialized', {
      assessmentType,
      assessmentId,
      sessionId,
      userId
    });

    // Save initial empty session
    this.saveSessionImmediate();

    return this.currentSession;
  }

  /**
   * Update a question's text (when it's first asked)
   */
  setQuestionText(questionNumber: number, questionText: string): void {
    if (!this.currentSession) {
      log.warn('No active PHQ session.');
      return;
    }

    const question = this.currentSession.questions.find(q => q.questionNumber === questionNumber);
    if (question) {
      question.questionText = questionText;
      this.currentSession.lastUpdated = new Date().toISOString();
      this.scheduleDelayedSave();
    }
  }

  /**
   * Record an answer to a question
   */
  recordAnswer(questionNumber: number, answer: number): void {
    if (!this.currentSession) {
      log.warn('No active PHQ session.');
      return;
    }

    const question = this.currentSession.questions.find(q => q.questionNumber === questionNumber);
    if (question) {
      question.answer = answer;
      question.answeredAt = new Date().toISOString();
      this.currentSession.lastUpdated = new Date().toISOString();

      log.debug(`PHQ answer recorded: Q${questionNumber} = ${answer}`);

      this.scheduleDelayedSave();
    }
  }

  /**
   * Record an invalid attempt for a question
   */
  recordInvalidAttempt(questionNumber: number): void {
    if (!this.currentSession) {
      log.warn('No active PHQ session.');
      return;
    }

    const question = this.currentSession.questions.find(q => q.questionNumber === questionNumber);
    if (question) {
      question.attempts++;

      // Mark as skipped after 3 attempts
      if (question.attempts >= 3) {
        question.skipped = true;
        log.debug(`PHQ question ${questionNumber} skipped after 3 attempts`);
      }

      this.currentSession.lastUpdated = new Date().toISOString();
      this.scheduleDelayedSave();
    }
  }

  /**
   * Add a message to the PHQ session (captures conversational flow)
   */
  addMessage(
    role: 'user' | 'assistant',
    content: string,
    messageType: string,
    additionalData?: Record<string, any>
  ): void {
    if (!this.currentSession) {
      log.warn('No active PHQ session.');
      return;
    }

    const message: PhqSessionMessage = {
      id: `phq-msg-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
      role,
      content,
      timestamp: new Date().toISOString(),
      messageType,
      additionalData
    };

    this.currentSession.messages.push(message);
    this.currentSession.lastUpdated = new Date().toISOString();

    // Schedule save after adding message
    this.scheduleDelayedSave();
  }

  /**
   * Complete the assessment with final score and severity
   */
  completeAssessment(totalScore: number, severity: string): void {
    if (!this.currentSession) {
      log.warn('No active PHQ session.');
      return;
    }

    this.currentSession.isCompleted = true;
    this.currentSession.completedAt = new Date().toISOString();
    this.currentSession.totalScore = totalScore;
    this.currentSession.severity = severity;
    this.currentSession.lastUpdated = new Date().toISOString();

    log.info('PHQ Session completed', {
      totalScore,
      severity,
      assessmentType: this.currentSession.assessmentType
    });

    // Save immediately when completed
    this.saveSessionImmediate();
  }

  /**
   * Get current session
   */
  getCurrentSession(): PhqSession | null {
    return this.currentSession;
  }

  /**
   * End the current session
   */
  endSession(): void {
    if (this.currentSession) {
      log.debug('PHQ Session ended', { assessmentId: this.currentSession.assessmentId });

      // Save one final time before clearing
      this.saveSessionImmediate();
      this.currentSession = null;
    }
  }

  /**
   * Schedule a delayed save to batch rapid updates
   */
  private scheduleDelayedSave(): void {
    if (this.saveTimer) {
      clearTimeout(this.saveTimer);
    }

    this.saveTimer = setTimeout(() => {
      this.saveSessionImmediate();
    }, this.saveDelay);
  }

  /**
   * DEPRECATED: Save the session immediately to phq-sessions container
   * NOTE: PHQ data is now saved directly in chat transcript messages with metadata
   * This method is kept for reference but is no longer actively saving
   */
  private async saveSessionImmediate(): Promise<void> {
    // Deprecated - PHQ data now flows through chatTranscriptService only
    // Keeping state management for Jekyll agent's local tracking
    log.info('PHQ session state updated (auto-save to blob deprecated - data saved via chat transcripts)');
  }
}

// Export singleton instance
export const phqSessionService = new PhqSessionService();

/**
 * Session Voice Recording Service
 *
 * Handles continuous recording of ALL user speech throughout the entire session
 * across all agents. Only captures audio when the user is speaking (using VAD),
 * avoiding silence/whitespace in the final recording.
 *
 * Recordings are saved to Azure Blob Storage in the audio-uploads container
 * with the naming pattern: userId_sessionId_timestamp.wav at 44100Hz.
 */

import { uploadToAzureBlob } from './azure';
import { convertAudioToWav } from './audio';
import { getUserId } from '@/utils';
import { Logger } from '@/utils/logger';

const log = Logger.create('SessionVoiceRecording');

export interface SessionRecordingState {
  isRecording: boolean;
  isCapturing: boolean; // Currently capturing user speech
  totalDuration: number; // Total time recording has been active (seconds)
  capturedDuration: number; // Actual audio captured (seconds, excluding silence)
  error?: string;
}

export interface SessionRecordingResult {
  audioUrl: string;
  fileName: string;
  totalDuration: number;
  capturedDuration: number;
  sizeBytes: number;
}

class SessionVoiceRecordingService {
  private mediaRecorder: MediaRecorder | null = null;
  private audioChunks: Blob[] = [];
  private stream: MediaStream | null = null;
  private sessionStartTime: number = 0;
  private captureStartTime: number = 0; // When current capture segment started
  private totalCapturedDuration: number = 0; // Accumulated captured audio duration
  private isCurrentlyCapturing: boolean = false;
  private sessionId: string | null = null;
  private userId: string | null = null;
  private audioContext: AudioContext | null = null;
  private analyser: AnalyserNode | null = null;
  private audioLevelCheckInterval: NodeJS.Timeout | null = null;

  // Audio level thresholds for filtering out non-speech
  private readonly MIN_AUDIO_LEVEL = 0.02; // Minimum RMS level (0-1 scale) to consider as speech
  private readonly SPEECH_CONFIRMATION_THRESHOLD = 0.05; // Stronger signal = definitely speech

  // Recording configuration
  // NOTE: We prefer audio/wav for Azure Speech API compatibility
  // WebM/Opus is NOT supported by Azure Speech Fast Transcription API
  private readonly RECORDING_OPTIONS = {
    mimeType: 'audio/wav', // Preferred - universally supported by Azure Speech
    audioBitsPerSecond: 128000
  };

  /**
   * Check if recording is supported in the current browser
   */
  isRecordingSupported(): boolean {
    return !!(
      navigator.mediaDevices &&
      typeof navigator.mediaDevices.getUserMedia === 'function' &&
      'MediaRecorder' in window
    );
  }

  /**
   * Start the session recording
   * @param sessionId Session ID for file naming
   * @param userId User ID for file naming
   */
  async startSessionRecording(sessionId: string, userId: string): Promise<void> {
    try {
      if (this.mediaRecorder && this.mediaRecorder.state === 'recording') {
        log.warn('Session Recording: Already recording');
        return;
      }

      log.info('STARTING SESSION-WIDE VOICE RECORDING');

      this.sessionId = sessionId;
      this.userId = userId;
      this.audioChunks = [];
      this.sessionStartTime = Date.now();
      this.totalCapturedDuration = 0;
      this.isCurrentlyCapturing = false;

      // Request microphone access with settings optimized for speech
      // 16kHz sample rate is optimal for speech recognition
      this.stream = await navigator.mediaDevices.getUserMedia({
        audio: {
          echoCancellation: true,
          noiseSuppression: true,
          autoGainControl: true,
          sampleRate: 16000, // Optimal for speech recognition
          channelCount: 1 // Mono for voice
        }
      });

      // Determine best supported MIME type for Azure Speech API compatibility
      // Priority: WAV > OGG (with opus) > MP4 > WebM (last resort, may not work)
      let mimeType = this.RECORDING_OPTIONS.mimeType;
      if (!MediaRecorder.isTypeSupported(mimeType)) {
        const fallbackTypes = [
          'audio/ogg;codecs=opus', // Supported by Azure Speech
          'audio/mp4',             // Supported by Azure Speech
          'audio/webm;codecs=opus', // May NOT work with Azure Speech - avoid if possible
          'audio/webm'
        ];

        for (const type of fallbackTypes) {
          if (MediaRecorder.isTypeSupported(type)) {
            mimeType = type;
            log.warn(`Session Recording: WAV not supported, using fallback: ${type}`);
            if (type.includes('webm')) {
              log.warn('Session Recording: WebM format may NOT be compatible with Azure Speech API');
            }
            break;
          }
        }
      }

      log.info(`Session Recording: Using MIME type: ${mimeType}`);

      // Create media recorder
      this.mediaRecorder = new MediaRecorder(this.stream, {
        mimeType,
        audioBitsPerSecond: this.RECORDING_OPTIONS.audioBitsPerSecond
      });

      // Handle data availability
      this.mediaRecorder.ondataavailable = (event) => {
        if (event.data.size > 0) {
          this.audioChunks.push(event.data);
          log.debug(`Session Recording: Chunk captured (${event.data.size} bytes)`);
        }
      };

      // Handle errors
      this.mediaRecorder.onerror = (event: Event) => {
        log.error('Session Recording: MediaRecorder error', event);
      };

      // Handle stop
      this.mediaRecorder.onstop = () => {
        log.info('Session Recording: MediaRecorder stopped');
        if (this.stream) {
          this.stream.getTracks().forEach(track => track.stop());
          this.stream = null;
        }
      };

      // Set up audio analysis for client-side level checking
      this.setupAudioAnalysis();

      // Start recording - but we'll control when to actually request data
      // Request data every 100ms for fine-grained control
      this.mediaRecorder.start(100);

      log.info(`Session Recording: Started for session ${sessionId}`);

    } catch (error) {
      log.error('Session Recording: Failed to start', error);

      let errorMessage = 'Failed to start session recording';
      if (error instanceof Error) {
        if (error.name === 'NotAllowedError' || error.name === 'PermissionDeniedError') {
          errorMessage = 'Microphone permission denied';
        } else if (error.name === 'NotFoundError') {
          errorMessage = 'No microphone found';
        } else {
          errorMessage = `Recording error: ${error.message}`;
        }
      }

      throw new Error(errorMessage);
    }
  }

  /**
   * Set up Web Audio API for real-time audio level analysis
   */
  private setupAudioAnalysis(): void {
    if (!this.stream) {
      return;
    }

    try {
      // Create audio context and analyser
      this.audioContext = new (window.AudioContext || (window as any).webkitAudioContext)();
      this.analyser = this.audioContext.createAnalyser();
      this.analyser.fftSize = 2048;
      this.analyser.smoothingTimeConstant = 0.8;

      // Connect stream to analyser
      const source = this.audioContext.createMediaStreamSource(this.stream);
      source.connect(this.analyser);

      log.debug('Session Recording: Audio analysis setup complete');
    } catch (error) {
      log.warn('Session Recording: Could not setup audio analysis', { error });
    }
  }

  /**
   * Get current audio level (RMS) from the microphone
   * @returns Audio level between 0 and 1
   */
  private getAudioLevel(): number {
    if (!this.analyser) {
      return 0;
    }

    const bufferLength = this.analyser.frequencyBinCount;
    const dataArray = new Uint8Array(bufferLength);
    this.analyser.getByteTimeDomainData(dataArray);

    // Calculate RMS (Root Mean Square) for audio level
    let sum = 0;
    for (let i = 0; i < bufferLength; i++) {
      const normalized = (dataArray[i] - 128) / 128; // Normalize to -1 to 1
      sum += normalized * normalized;
    }
    const rms = Math.sqrt(sum / bufferLength);

    return rms;
  }

  /**
   * Check if current audio level indicates speech
   */
  private isSpeechLevel(): boolean {
    const level = this.getAudioLevel();

    // Speech typically has RMS > 0.02, strong speech > 0.05
    const isSpeech = level >= this.MIN_AUDIO_LEVEL;

    if (level >= this.SPEECH_CONFIRMATION_THRESHOLD) {
      // Strong signal - definitely speech
      return true;
    } else if (isSpeech) {
      // Weak but above threshold - could be speech or ambient noise
      // Let server VAD be the final decision maker
      return true;
    }

    return false;
  }

  /**
   * Start monitoring audio levels during capture
   */
  private startAudioLevelMonitoring(): void {
    // Clear any existing interval
    this.stopAudioLevelMonitoring();

    // Check audio level every 100ms while capturing
    this.audioLevelCheckInterval = setInterval(() => {
      if (!this.isCurrentlyCapturing) {
        this.stopAudioLevelMonitoring();
        return;
      }

      // If audio level drops below threshold for too long, stop capturing
      if (!this.isSpeechLevel()) {
        log.debug('Session Recording: Audio level dropped below speech threshold - stopping capture');
        this.onUserSpeechStop();
      }
    }, 100);
  }

  /**
   * Stop monitoring audio levels
   */
  private stopAudioLevelMonitoring(): void {
    if (this.audioLevelCheckInterval) {
      clearInterval(this.audioLevelCheckInterval);
      this.audioLevelCheckInterval = null;
    }
  }

  /**
   * Notify that user started speaking - start capturing audio
   */
  onUserSpeechStart(): void {
    if (!this.mediaRecorder || this.mediaRecorder.state !== 'recording') {
      return;
    }

    if (this.isCurrentlyCapturing) {
      return; // Already capturing
    }

    // Double-check with client-side audio level analysis
    if (!this.isSpeechLevel()) {
      const level = this.getAudioLevel();
      log.debug(`Session Recording: VAD detected speech but audio level too low (${level.toFixed(3)}) - filtering out ambient noise`);
      return;
    }

    log.debug('Session Recording: User speech started - capturing audio');
    this.isCurrentlyCapturing = true;
    this.captureStartTime = Date.now();

    // Start periodic audio level checking to ensure we stop if level drops
    this.startAudioLevelMonitoring();

    // Request data to ensure we capture from this moment
    // The MediaRecorder will continue collecting data automatically
  }

  /**
   * Notify that user stopped speaking - stop capturing audio
   */
  onUserSpeechStop(): void {
    if (!this.mediaRecorder || this.mediaRecorder.state !== 'recording') {
      return;
    }

    if (!this.isCurrentlyCapturing) {
      return; // Not currently capturing
    }

    log.debug('Session Recording: User speech stopped - pausing capture');

    // Stop audio level monitoring
    this.stopAudioLevelMonitoring();

    // Calculate duration of this capture segment
    const segmentDuration = (Date.now() - this.captureStartTime) / 1000;
    this.totalCapturedDuration += segmentDuration;

    log.debug(`Session Recording: Captured ${segmentDuration.toFixed(1)}s (total: ${this.totalCapturedDuration.toFixed(1)}s)`);

    this.isCurrentlyCapturing = false;

    // Request data to finalize this segment
    if (this.mediaRecorder.state === 'recording') {
      this.mediaRecorder.requestData();
    }
  }

  /**
   * Stop the session recording and save to Azure Blob Storage
   */
  async stopSessionRecording(): Promise<SessionRecordingResult | null> {
    try {
      if (!this.mediaRecorder || this.mediaRecorder.state === 'inactive') {
        log.warn('Session Recording: No active recording to stop');
        return null;
      }

      log.info('STOPPING SESSION-WIDE VOICE RECORDING');

      // Stop audio level monitoring
      this.stopAudioLevelMonitoring();

      // If currently capturing, finalize the duration
      if (this.isCurrentlyCapturing) {
        const segmentDuration = (Date.now() - this.captureStartTime) / 1000;
        this.totalCapturedDuration += segmentDuration;
        this.isCurrentlyCapturing = false;
      }

      const totalDuration = (Date.now() - this.sessionStartTime) / 1000;

      return new Promise<SessionRecordingResult | null>((resolve, reject) => {
        if (!this.mediaRecorder) {
          resolve(null);
          return;
        }

        this.mediaRecorder.onstop = async () => {
          try {
            // Stop all tracks
            if (this.stream) {
              this.stream.getTracks().forEach(track => track.stop());
              this.stream = null;
            }

            // Clean up audio context
            if (this.audioContext) {
              await this.audioContext.close();
              this.audioContext = null;
              this.analyser = null;
            }

            // Check if we have audio data
            if (this.audioChunks.length === 0) {
              log.warn('Session Recording: No audio data captured');
              resolve(null);
              return;
            }

            log.info('Session Recording: Processing audio', { chunks: this.audioChunks.length, totalDuration: totalDuration.toFixed(1), capturedSpeech: this.totalCapturedDuration.toFixed(1) });

            // Create blob from chunks
            const recordedBlob = new Blob(this.audioChunks, {
              type: this.mediaRecorder?.mimeType || 'audio/webm'
            });
            const sizeBytes = recordedBlob.size;

            log.debug(`Session Recording: Created blob (${(sizeBytes / 1024 / 1024).toFixed(2)} MB)`);

            // Convert to WAV format at 44100Hz
            log.info('Session Recording: Converting to 44100Hz WAV...');
            const wavBlob = await convertAudioToWav(
              new File([recordedBlob], 'session-recording.webm', { type: recordedBlob.type }),
              (progress) => {
                log.debug(`Session Recording: Conversion progress: ${progress.toFixed(1)}%`);
              }
            );

            log.debug(`Session Recording: Converted to WAV (${(wavBlob.size / 1024 / 1024).toFixed(2)} MB)`);

            // Generate filename: userId_sessionId_timestamp.wav
            const timestamp = Date.now();
            const fileName = `${this.userId}_${this.sessionId}_${timestamp}.wav`;

            log.info(`Session Recording: Uploading as ${fileName}...`);

            // Upload to Azure Blob Storage (audio-uploads container)
            const audioUrl = await uploadToAzureBlob(
              wavBlob,
              fileName,
              (uploadProgress) => {
                log.debug(`Session Recording: Upload progress: ${uploadProgress}%`);
              },
              this.userId || getUserId()
            );

            log.info(`Session Recording: Upload complete - ${audioUrl}`);

            const result: SessionRecordingResult = {
              audioUrl,
              fileName,
              totalDuration,
              capturedDuration: this.totalCapturedDuration,
              sizeBytes: wavBlob.size
            };

            // Clear chunks
            this.audioChunks = [];

            resolve(result);

          } catch (error) {
            log.error('Session Recording: Error processing/uploading', error);
            reject(error);
          }
        };

        // Stop the recorder
        this.mediaRecorder.stop();
      });

    } catch (error) {
      log.error('Session Recording: Error stopping recording', error);
      throw error;
    }
  }

  /**
   * Cancel recording without saving
   */
  cancelRecording(): void {
    try {
      log.info('Session Recording: Cancelling...');

      if (this.mediaRecorder && this.mediaRecorder.state !== 'inactive') {
        this.mediaRecorder.stop();
      }

      if (this.stream) {
        this.stream.getTracks().forEach(track => track.stop());
        this.stream = null;
      }

      this.audioChunks = [];
      this.isCurrentlyCapturing = false;
      this.totalCapturedDuration = 0;

      log.info('Session Recording: Cancelled');

    } catch (error) {
      log.error('Session Recording: Error cancelling', error);
    }
  }

  /**
   * Check if currently recording the session
   */
  isRecording(): boolean {
    return this.mediaRecorder !== null && this.mediaRecorder.state === 'recording';
  }

  /**
   * Get current recording state
   */
  getState(): SessionRecordingState {
    const totalDuration = this.sessionStartTime > 0
      ? (Date.now() - this.sessionStartTime) / 1000
      : 0;

    return {
      isRecording: this.isRecording(),
      isCapturing: this.isCurrentlyCapturing,
      totalDuration,
      capturedDuration: this.totalCapturedDuration,
    };
  }

  /**
   * Cleanup resources
   */
  cleanup(): void {
    this.cancelRecording();
    this.sessionId = null;
    this.userId = null;
  }
}

// Export singleton instance
export const sessionVoiceRecordingService = new SessionVoiceRecordingService();

/**
 * Smart Band Data Service
 * Handles collecting sensor data from Microsoft Band devices
 * Based on Microsoft Band SDK: https://github.com/mattleibow/Microsoft-Band-SDK-Bindings
 */

import { env } from '@/utils/env';
import { Logger } from '@/utils/logger';

const log = Logger.create('SmartBandData');

export interface SmartBandSensorData {
  // Accelerometer data
  accelerometer?: {
    x: number; // m/s²
    y: number; // m/s²
    z: number; // m/s²
    timestamp: string;
  };

  // Gyroscope data
  gyroscope?: {
    x: number; // °/s
    y: number; // °/s
    z: number; // °/s
    timestamp: string;
  };

  // Distance/Speed/Pace
  motion?: {
    distance: number; // cm (cumulative)
    speed: number; // cm/s
    pace: number; // ms/m
    motionType: 'idle' | 'walking' | 'jogging' | 'running' | 'unknown';
    timestamp: string;
  };

  // Heart rate
  heartRate?: {
    bpm: number; // beats per minute
    quality: 'acquiring' | 'locked' | 'poor';
    timestamp: string;
  };

  // Pedometer
  pedometer?: {
    totalSteps: number; // cumulative since last reset
    timestamp: string;
  };

  // Skin temperature
  skinTemperature?: {
    celsius: number;
    timestamp: string;
  };

  // UV exposure
  uvExposure?: {
    exposureLevel: 'none' | 'low' | 'medium' | 'high' | 'veryHigh';
    indexValue: number;
    timestamp: string;
  };

  // Device contact
  deviceContact?: {
    isWorn: boolean;
    timestamp: string;
  };

  // Calories
  calories?: {
    totalBurned: number; // cumulative since factory reset
    timestamp: string;
  };
}

export interface SmartBandDataSnapshot {
  userId: string;
  snapshotId: string;
  collectedAt: string;
  deviceInfo?: {
    firmwareVersion?: string;
    hardwareVersion?: string;
    serialNumber?: string;
  };
  sensorData: SmartBandSensorData;
  metadata: {
    source: 'microsoft-band-sdk';
    collectionDurationMs?: number;
    errors?: string[];
  };
}

class SmartBandDataService {
  private isEnabled: boolean;
  private isCollecting: boolean = false;

  constructor() {
    // Check if smart band feature is enabled via environment variable
    this.isEnabled = false;
  }

  /**
   * Check if smart band feature is enabled
   */
  isFeatureEnabled(): boolean {
    return this.isEnabled;
  }

  /**
   * Check if a Microsoft Band device is currently connected
   * Calls the local Windows Service REST API
   */
  async isDeviceConnected(): Promise<boolean> {
    if (!this.isEnabled) {
      return false;
    }

    try {
      log.debug('Checking for Microsoft Band device via local service...');

      // Call the local Band Service REST API
      const bandServiceUrl = 'http://localhost:8765';
      const response = await fetch(`${bandServiceUrl}/api/band/status`, {
        method: 'GET',
        headers: {
          'Content-Type': 'application/json'
        }
      });

      if (!response.ok) {
        log.warn('Band service not responding', { status: response.status });
        return false;
      }

      const result = await response.json();
      log.debug('Device status', { connected: result.isConnected });

      return result.isConnected || false;
    } catch (error) {
      log.error('Error checking Band device connection', error);
      log.info('Make sure the Band Service is running (BehavioralHealthSystem.BandService)');
      return false;
    }
  }

  /**
   * Collect sensor data snapshot from Microsoft Band
   * This is a silent operation that doesn't notify the user
   */
  async collectDataSnapshot(userId: string): Promise<SmartBandDataSnapshot | null> {
    if (!this.isEnabled) {
      log.debug('Smart Band feature is disabled');
      return null;
    }

    if (this.isCollecting) {
      log.debug('Already collecting Smart Band data');
      return null;
    }

    try {
      this.isCollecting = true;
      const startTime = Date.now();

      log.debug('Starting silent Smart Band data collection...');

      // Check device connection
      const isConnected = await this.isDeviceConnected();
      if (!isConnected) {
        log.debug('No Microsoft Band device connected');
        return null;
      }

      // Collect sensor data from local Band Service
      const snapshot = await this.collectAllSensors(userId);

      if (!snapshot) {
        log.debug('Failed to collect sensor data');
        return null;
      }

      const duration = Date.now() - startTime;

      // Add collection duration to metadata
      snapshot.metadata.collectionDurationMs = duration;

      log.info('Smart Band data collection complete', { durationMs: duration });

      return snapshot;
    } catch (error) {
      log.error('Error collecting Smart Band data', error);

      // Return snapshot with error info
      return {
        userId,
        snapshotId: `error-${Date.now()}`,
        collectedAt: new Date().toISOString(),
        sensorData: {},
        metadata: {
          source: 'microsoft-band-sdk',
          errors: [error instanceof Error ? error.message : 'Unknown error']
        }
      };
    } finally {
      this.isCollecting = false;
    }
  }

  /**
   * Collect data from all available sensors via local Band Service API
   */
  private async collectAllSensors(userId: string): Promise<SmartBandDataSnapshot | null> {
    try {
      log.debug('Collecting sensor data from Band Service...');

      // Call the local Band Service REST API to collect data
      const bandServiceUrl = 'http://localhost:8765';
      const response = await fetch(`${bandServiceUrl}/api/band/collect`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({ userId })
      });

      if (!response.ok) {
        throw new Error(`Band service error: ${response.status}`);
      }

      const result = await response.json();

      if (!result.success || !result.data) {
        throw new Error(result.error || 'Failed to collect sensor data');
      }

      // Map the Band Service response to our format
      const snapshot: SmartBandDataSnapshot = {
        userId: result.data.userId,
        snapshotId: result.data.snapshotId,
        collectedAt: result.data.collectedAt,
        deviceInfo: result.data.deviceInfo,
        sensorData: this.mapSensorData(result.data.sensorData),
        metadata: {
          source: 'microsoft-band-sdk',
          ...result.data.metadata
        }
      };

      log.info('Sensor data collected successfully');
      return snapshot;

    } catch (error) {
      log.error('Error collecting sensor data', error);
      throw error;
    }
  }

  /**
   * Map Band Service sensor data format to our frontend format
   */
  private mapSensorData(bandData: any): SmartBandSensorData {
    const sensorData: SmartBandSensorData = {};

    if (bandData.accelerometer) {
      sensorData.accelerometer = {
        x: bandData.accelerometer.x,
        y: bandData.accelerometer.y,
        z: bandData.accelerometer.z,
        timestamp: bandData.accelerometer.timestamp
      };
    }

    if (bandData.gyroscope) {
      sensorData.gyroscope = {
        x: bandData.gyroscope.x,
        y: bandData.gyroscope.y,
        z: bandData.gyroscope.z,
        timestamp: bandData.gyroscope.timestamp
      };
    }

    if (bandData.motion) {
      sensorData.motion = {
        distance: bandData.motion.distanceCm,
        speed: bandData.motion.speedCmPerSecond,
        pace: bandData.motion.paceMsPerMeter,
        motionType: bandData.motion.motionType?.toLowerCase() || 'unknown',
        timestamp: bandData.motion.timestamp
      };
    }

    if (bandData.heartRate) {
      sensorData.heartRate = {
        bpm: bandData.heartRate.bpm,
        quality: bandData.heartRate.quality?.toLowerCase() || 'poor',
        timestamp: bandData.heartRate.timestamp
      };
    }

    if (bandData.pedometer) {
      sensorData.pedometer = {
        totalSteps: bandData.pedometer.totalSteps,
        timestamp: bandData.pedometer.timestamp
      };
    }

    if (bandData.skinTemperature) {
      sensorData.skinTemperature = {
        celsius: bandData.skinTemperature.temperatureCelsius,
        timestamp: bandData.skinTemperature.timestamp
      };
    }

    if (bandData.uvExposure) {
      sensorData.uvExposure = {
        exposureLevel: bandData.uvExposure.exposureLevel?.toLowerCase() || 'none',
        indexValue: bandData.uvExposure.indexLevel,
        timestamp: bandData.uvExposure.timestamp
      };
    }

    if (bandData.deviceContact) {
      sensorData.deviceContact = {
        isWorn: bandData.deviceContact.isWorn,
        timestamp: bandData.deviceContact.timestamp
      };
    }

    if (bandData.calories) {
      sensorData.calories = {
        totalBurned: bandData.calories.totalCalories,
        timestamp: bandData.calories.timestamp
      };
    }

    return sensorData;
  }

  /**
   * Save collected snapshot to Azure Functions backend
   */
  async saveSnapshot(snapshot: SmartBandDataSnapshot): Promise<boolean> {
    try {
      const apiBaseUrl = env.API_BASE_URL;
      const endpoint = `${apiBaseUrl}/SaveSmartBandData`;

      log.debug('Saving Smart Band data to:', { endpoint });

      const response = await fetch(endpoint, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify(snapshot)
      });

      if (!response.ok) {
        const errorText = await response.text();
        throw new Error(`Failed to save Smart Band data: ${response.status} - ${errorText}`);
      }

      const result = await response.json();
      log.info('Smart Band data saved successfully', result);

      return true;
    } catch (error) {
      log.error('Error saving Smart Band data', error);
      return false;
    }
  }

  /**
   * Collect and save Smart Band data in one operation
   * This is the main method that Jekyll will call
   */
  async collectAndSave(userId: string): Promise<{
    success: boolean;
    snapshot?: SmartBandDataSnapshot;
    error?: string;
  }> {
    if (!this.isEnabled) {
      return {
        success: false,
        error: 'Smart Band feature is not enabled'
      };
    }

    try {
      log.debug('Collecting Smart Band data for user', { userId });

      // Collect snapshot
      const snapshot = await this.collectDataSnapshot(userId);

      if (!snapshot) {
        return {
          success: false,
          error: 'No device connected or data collection failed'
        };
      }

      // Save to blob storage via Azure Function
      const saved = await this.saveSnapshot(snapshot);

      if (!saved) {
        return {
          success: false,
          snapshot,
          error: 'Failed to save data to storage'
        };
      }

      return {
        success: true,
        snapshot
      };
    } catch (error) {
      log.error('Error in collectAndSave', error);
      return {
        success: false,
        error: error instanceof Error ? error.message : 'Unknown error'
      };
    }
  }
}

// Export singleton instance
export const smartBandDataService = new SmartBandDataService();
export default smartBandDataService;

/**
 * WebRTC Audio Streaming Service for real-time audio communication
 * Handles continuous microphone input and audio output streaming
 */

import { Logger } from '@/utils/logger';

const log = Logger.create('WebRTCAudio');

export interface WebRTCAudioConfig {
  sampleRate?: number;
  channelCount?: number;
  bitDepth?: number;
  bufferSize?: number;
  echoCancellation?: boolean;
  noiseSuppression?: boolean;
  autoGainControl?: boolean;
}

export interface AudioStreamEvent {
  type: 'audio_data' | 'stream_started' | 'stream_stopped' | 'error';
  data?: ArrayBuffer;
  timestamp?: number;
  error?: string;
}

export class WebRTCAudioService extends EventTarget {
  private mediaStream: MediaStream | null = null;
  private audioContext: AudioContext | null = null;
  private sourceNode: MediaStreamAudioSourceNode | null = null;
  private processorNode: ScriptProcessorNode | null = null;
  private gainNode: GainNode | null = null;
  private isStreaming = false;
  private config: WebRTCAudioConfig;
  private playbackQueue: ArrayBuffer[] = [];
  private isPlayingAudio = false;

  constructor(config: WebRTCAudioConfig = {}) {
    super();
    this.config = {
      sampleRate: 24000, // Matching GPT-Realtime expected sample rate
      channelCount: 1,
      bitDepth: 16,
      bufferSize: 4096,
      echoCancellation: true,
      noiseSuppression: true,
      autoGainControl: true,
      ...config
    };
  }

  async initialize(): Promise<void> {
    try {
      // Request microphone access
      this.mediaStream = await navigator.mediaDevices.getUserMedia({
        audio: {
          sampleRate: this.config.sampleRate,
          channelCount: this.config.channelCount,
          echoCancellation: this.config.echoCancellation,
          noiseSuppression: this.config.noiseSuppression,
          autoGainControl: this.config.autoGainControl
        },
        video: false
      });

      // Create audio context
      this.audioContext = new (window.AudioContext || (window as any).webkitAudioContext)({
        sampleRate: this.config.sampleRate
      });

      // Create audio nodes
      this.sourceNode = this.audioContext.createMediaStreamSource(this.mediaStream);
      this.gainNode = this.audioContext.createGain();
      this.processorNode = this.audioContext.createScriptProcessor(
        this.config.bufferSize,
        this.config.channelCount,
        this.config.channelCount
      );

      // Connect audio nodes
      this.sourceNode.connect(this.gainNode);
      this.gainNode.connect(this.processorNode);
      this.processorNode.connect(this.audioContext.destination);

      // Handle audio processing
      this.processorNode.onaudioprocess = (event) => {
        if (this.isStreaming) {
          this.processAudioData(event);
        }
      };

      log.info('WebRTC Audio Service initialized');
      this.dispatchEvent(new CustomEvent('initialized'));

    } catch (error) {
      log.error('Failed to initialize WebRTC Audio Service', error);
      const errorMessage = error instanceof Error ? error.message : 'Unknown error';
      this.dispatchEvent(new CustomEvent('error', { detail: { error: errorMessage } }));
      throw error;
    }
  }

  async startStreaming(): Promise<void> {
    if (!this.audioContext || !this.processorNode) {
      throw new Error('Audio service not initialized');
    }

    if (this.audioContext.state === 'suspended') {
      await this.audioContext.resume();
    }

    this.isStreaming = true;
    log.debug('Audio streaming started');
    this.dispatchEvent(new CustomEvent('stream_started'));
  }

  stopStreaming(): void {
    this.isStreaming = false;
    log.debug('Audio streaming stopped');
    this.dispatchEvent(new CustomEvent('stream_stopped'));
  }

  setGain(gain: number): void {
    if (this.gainNode) {
      this.gainNode.gain.value = Math.max(0, Math.min(2, gain));
    }
  }

  private processAudioData(event: AudioProcessingEvent): void {
    const inputBuffer = event.inputBuffer;

    // Get input audio data
    const inputData = inputBuffer.getChannelData(0);

    // Convert Float32Array to Int16Array (PCM16)
    const pcmData = this.float32ToPCM16(inputData);

    // Create ArrayBuffer
    const audioBuffer = pcmData.buffer.slice(
      pcmData.byteOffset,
      pcmData.byteOffset + pcmData.byteLength
    );

    // Emit audio data event
    this.dispatchEvent(new CustomEvent('audio_data', {
      detail: {
        audioData: audioBuffer,
        timestamp: Date.now(),
        sampleRate: this.config.sampleRate,
        channels: this.config.channelCount
      }
    }));

    // Note: Playback handling is done separately via playAudio method
  }

  private float32ToPCM16(float32Array: Float32Array): Int16Array {
    const pcm16Array = new Int16Array(float32Array.length);
    for (let i = 0; i < float32Array.length; i++) {
      // Clamp to [-1, 1] and convert to 16-bit integer
      const sample = Math.max(-1, Math.min(1, float32Array[i]));
      pcm16Array[i] = sample * 0x7FFF;
    }
    return pcm16Array;
  }

  private pcm16ToFloat32(pcm16Array: Int16Array): Float32Array {
    const float32Array = new Float32Array(pcm16Array.length);
    for (let i = 0; i < pcm16Array.length; i++) {
      float32Array[i] = pcm16Array[i] / 0x7FFF;
    }
    return float32Array;
  }

  async playAudio(audioData: ArrayBuffer): Promise<void> {
    if (!this.audioContext) {
      log.warn('Audio context not available for playback');
      return;
    }

    this.playbackQueue.push(audioData);

    // If not already playing, start playback
    if (!this.isPlayingAudio) {
      this.processPlaybackQueue();
    }
  }

  private async processPlaybackQueue(): Promise<void> {
    if (this.playbackQueue.length === 0 || !this.audioContext) {
      this.isPlayingAudio = false;
      return;
    }

    this.isPlayingAudio = true;

    try {
      const audioData = this.playbackQueue.shift()!;

      // Convert PCM16 to AudioBuffer
      const audioBuffer = await this.createAudioBuffer(audioData);

      // Create and play audio source
      const source = this.audioContext.createBufferSource();
      source.buffer = audioBuffer;
      source.connect(this.audioContext.destination);

      source.onended = () => {
        // Continue with next audio in queue
        this.processPlaybackQueue();
      };

      source.start();

    } catch (error) {
      log.error('Error playing audio', error);
      this.isPlayingAudio = false;
    }
  }

  private async createAudioBuffer(pcmData: ArrayBuffer): Promise<AudioBuffer> {
    if (!this.audioContext) {
      throw new Error('Audio context not available');
    }

    // Convert ArrayBuffer to Int16Array
    const pcm16Array = new Int16Array(pcmData);

    // Convert to Float32Array
    const float32Array = this.pcm16ToFloat32(pcm16Array);

    // Create AudioBuffer
    const audioBuffer = this.audioContext.createBuffer(
      this.config.channelCount!,
      float32Array.length,
      this.config.sampleRate!
    );

    // Copy data to AudioBuffer
    audioBuffer.getChannelData(0).set(float32Array);

    return audioBuffer;
  }

  async getAudioDevices(): Promise<MediaDeviceInfo[]> {
    try {
      const devices = await navigator.mediaDevices.enumerateDevices();
      return devices.filter(device => device.kind === 'audioinput');
    } catch (error) {
      log.error('Error getting audio devices', error);
      return [];
    }
  }

  async switchAudioDevice(deviceId: string): Promise<void> {
    if (this.mediaStream) {
      // Stop current stream
      this.mediaStream.getTracks().forEach(track => track.stop());
    }

    try {
      // Start new stream with selected device
      this.mediaStream = await navigator.mediaDevices.getUserMedia({
        audio: {
          deviceId: { exact: deviceId },
          sampleRate: this.config.sampleRate,
          channelCount: this.config.channelCount,
          echoCancellation: this.config.echoCancellation,
          noiseSuppression: this.config.noiseSuppression,
          autoGainControl: this.config.autoGainControl
        },
        video: false
      });

      // Reconnect audio source
      if (this.sourceNode && this.audioContext) {
        this.sourceNode.disconnect();
        this.sourceNode = this.audioContext.createMediaStreamSource(this.mediaStream);
        this.sourceNode.connect(this.gainNode!);
      }

      log.info('Switched to audio device', { deviceId });
      this.dispatchEvent(new CustomEvent('device_changed', { detail: { deviceId } }));

    } catch (error) {
      log.error('Error switching audio device', error);
      const errorMessage = error instanceof Error ? error.message : 'Unknown error';
      this.dispatchEvent(new CustomEvent('error', { detail: { error: errorMessage } }));
      throw error;
    }
  }

  getVoiceActivityLevel(): number {
    if (!this.audioContext || !this.sourceNode) {
      return 0;
    }

    // Simple voice activity detection based on audio level
    // In a real implementation, you might want more sophisticated VAD
    try {
      const analyser = this.audioContext.createAnalyser();
      this.sourceNode.connect(analyser);
      analyser.fftSize = 256;

      const dataArray = new Uint8Array(analyser.frequencyBinCount);
      analyser.getByteFrequencyData(dataArray);

      // Calculate average amplitude
      const average = dataArray.reduce((sum, value) => sum + value, 0) / dataArray.length;
      return average / 255; // Normalize to 0-1

    } catch (error) {
      return 0;
    }
  }

  dispose(): void {
    this.stopStreaming();

    if (this.mediaStream) {
      this.mediaStream.getTracks().forEach(track => track.stop());
      this.mediaStream = null;
    }

    if (this.processorNode) {
      this.processorNode.disconnect();
      this.processorNode = null;
    }

    if (this.sourceNode) {
      this.sourceNode.disconnect();
      this.sourceNode = null;
    }

    if (this.gainNode) {
      this.gainNode.disconnect();
      this.gainNode = null;
    }

    if (this.audioContext && this.audioContext.state !== 'closed') {
      this.audioContext.close();
      this.audioContext = null;
    }

    this.playbackQueue = [];

    log.debug('WebRTC Audio Service disposed');
  }

  get isInitialized(): boolean {
    return this.audioContext !== null && this.mediaStream !== null;
  }

  get isActive(): boolean {
    return this.isStreaming;
  }

  get sampleRate(): number {
    return this.config.sampleRate!;
  }
}

import React from 'react';
import { render } from '@testing-library/react';
import { vi, describe, test, expect } from 'vitest';

/**
 * Accessibility smoke tests.
 *
 * Full page rendering (Dashboard, Sessions) requires extensive mocking of
 * services, auth, hooks, and contexts. These tests validate that the key
 * accessibility utilities and components are defined and importable, and
 * check ARIA semantics on simple standalone elements.
 */

describe('Accessibility Tests', () => {
  test('AccessibleDialog component should be importable', async () => {
    const mod = await import('@/components/AccessibleDialog');
    expect(mod.AccessibleDialog).toBeDefined();
  });

  test('useAccessibility hook should be importable', async () => {
    const mod = await import('@/hooks/useAccessibility');
    expect(mod.useAccessibility).toBeDefined();
    expect(typeof mod.useAccessibility).toBe('function');
  });

  test('accessibility hooks should be importable', async () => {
    const mod = await import('@/hooks/accessibility');
    expect(mod).toBeDefined();
    // Should export common accessibility hooks
    expect(typeof mod.useAnnouncements).toBe('function');
  });

  test('Dashboard component should be importable', async () => {
    const mod = await import('@/pages/Dashboard');
    expect(mod.Dashboard).toBeDefined();
  });

  test('Sessions component should be importable', async () => {
    const mod = await import('@/pages/Sessions');
    expect(mod.default).toBeDefined();
  });

  test('should have proper heading hierarchy in rendered HTML', () => {
    // Test basic heading hierarchy with a simple component
    const TestPage = () => (
      <main id="main-content">
        <h1>Test Page</h1>
        <section>
          <h2>Section One</h2>
          <p>Content</p>
        </section>
        <section>
          <h2>Section Two</h2>
          <p>More content</p>
        </section>
      </main>
    );

    const { container } = render(<TestPage />);

    const main = container.querySelector('main');
    expect(main).toBeInTheDocument();
    expect(main).toHaveAttribute('id', 'main-content');

    const h1 = container.querySelector('h1');
    expect(h1).toBeInTheDocument();

    const h2s = container.querySelectorAll('h2');
    expect(h2s.length).toBeGreaterThan(0);

    // h1 should come before h2s
    const headings = Array.from(container.querySelectorAll('h1, h2'));
    expect(headings[0].tagName).toBe('H1');
  });

  test('should have proper ARIA labels on interactive elements', () => {
    const TestInteractive = () => (
      <div>
        <nav role="navigation" aria-label="Main navigation">
          <a href="/home">Home</a>
        </nav>
        <main id="main-content">
          <button aria-label="Close dialog">X</button>
          <input type="search" aria-label="Search sessions" />
        </main>
      </div>
    );

    const { container } = render(<TestInteractive />);

    const navigation = container.querySelector('[role="navigation"]');
    expect(navigation).toBeInTheDocument();
    expect(navigation).toHaveAttribute('aria-label');

    const main = container.querySelector('main');
    expect(main).toBeInTheDocument();
    expect(main).toHaveAttribute('id');

    const button = container.querySelector('button[aria-label]');
    expect(button).toBeInTheDocument();

    const searchInput = container.querySelector('input[type="search"]');
    expect(searchInput).toBeInTheDocument();
    expect(searchInput).toHaveAttribute('aria-label');
  });
});

